}
@media (max-width: 900px) { .welcome-grid { grid-template-columns: minmax(0, 1fr); } }
.panel {
  background: linear-gradient(180deg, #15101e, #0a0612);
  border: 2px solid #000;
  box-shadow: var(--pixel-edge), 0 0 0 2px #ff7a1a33;
