  box-shadow: var(--pixel-edge), 0 0 0 2px #ff7a1a, 0 0 20px #ff7a1a88;
  animation: pulse 1.2s ease-in-out infinite;
}
.daily-day { font-family: 'VT323', monospace; color: var(--ink-dim); font-size: 12px; }
.daily-icon { font-size: 26px; margin: 4px 0; }
.daily-label { font-family: 'VT323', monospace; font-size: 11px; color: var(--ink); }

.quest-list { display: flex; flex-direction: column; gap: 8px; }
.quest-row {
  display: flex; gap: 10px; align-items: center;
  background: #0e0816; border: 2px solid #000;
  box-shadow: var(--pixel-edge); padding: 10px;
}
.quest-row.done { border-color: var(--rune); box-shadow: var(--pixel-edge), 0 0 0 1px #4dffd488; }
.quest-icon { font-size: 28px; width: 36px; text-align: center; }
.quest-body { flex: 1; }
.quest-name { font-family: 'Cinzel', serif; font-weight: 800; font-size: 13px; color: var(--ink); letter-spacing: 0.08em; }
.quest-desc { font-family: 'VT323', monospace; color: var(--ink-dim); font-size: 14px; margin-bottom: 4px; }
.quest-bar { height: 6px; background: #00000099; border: 1px solid #000; }
.quest-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--rune), #4dffd4);
  transition: width 0.6s cubic-bezier(0.34,1.56,0.64,1);
  position: relative;
  overflow: hidden;
}
.quest-bar-fill::after {
  content: '';
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(90deg, transparent 40%, rgba(255,255,255,0.3) 60%, transparent 80%);
  animation: shine 2s infinite;
}
.quest-prog { font-family: 'VT323', monospace; font-size: 12px; color: var(--ink-dim); }
.quest-reward {
  font-family: 'VT323', monospace; font-size: 13px;
  text-align: right; min-width: 80px;
  color: var(--accent-2);
}

.welcome-actions {
  display: flex; flex-direction: column; align-items: stretch;
  gap: 10px; justify-content: center;
  margin-top: 8px;
}
.welcome-actions button { padding: 14px 22px; }

/* Avatar select */
.avatar-grid {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px;
  margin: 18px 0;
}
.avatar-card {
  background: #0e0816; border: 2px solid #000;
  box-shadow: var(--pixel-edge);
  padding: 14px 8px; cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  transition: transform 100ms, box-shadow 100ms;
}
.avatar-card:hover { transform: translateY(-3px); box-shadow: var(--pixel-edge), 0 4px 0 #000, 0 0 20px #ff7a1a55; }
.avatar-card.sel { border-color: var(--accent); box-shadow: var(--pixel-edge), 0 0 0 2px #ff7a1a, 0 0 30px #ff7a1a88; }
.avatar-icon { font-size: 38px; filter: drop-shadow(0 0 10px currentColor); }
.avatar-name { font-family: 'Cinzel', serif; font-weight: 800; font-size: 12px; }
.avatar-desc { font-family: 'VT323', monospace; font-size: 13px; color: var(--ink-dim); text-align: center; min-height: 24px; }
.name-input {
  width: 100%; padding: 12px 14px;
  background: #0a0612; border: 2px solid #000;
  box-shadow: var(--pixel-edge), inset 0 0 0 1px #4dffd444;
  color: var(--ink); font-family: 'JetBrains Mono', monospace;
  font-size: 16px; letter-spacing: 0.1em;
  outline: none;
}
.name-input:focus { box-shadow: var(--pixel-edge), 0 0 0 2px #ff7a1a, 0 0 20px #ff7a1a66; }

/* Skill Tree */
.skilltree-panel {
  width: min(1100px, 96vw); max-height: 88vh;
  background: linear-gradient(180deg, #0e1a26, #07060c);
  border: 2px solid #000; box-shadow: 0 0 0 2px #b362ff44, 0 30px 60px #000;
  padding: 20px; display: flex; flex-direction: column;
}
.st-header { display: flex; align-items: center; gap: 14px; padding-bottom: 12px; border-bottom: 1px dashed #ffffff22; }
.st-title { font-family: 'Cinzel', serif; font-weight: 800; font-size: 22px; color: var(--eldritch); letter-spacing: 0.15em; flex: 1; }
.st-sp { font-family: 'VT323', monospace; color: var(--rune); font-size: 22px; letter-spacing: 0.2em; }
.st-tabs { display: flex; gap: 6px; margin: 14px 0; flex-wrap: wrap; }
.st-tab {
  padding: 8px 14px; cursor: pointer;
  background: #0e0816; border: 2px solid #000; box-shadow: var(--pixel-edge);
  font-family: 'Cinzel', serif; font-weight: 800; font-size: 12px; letter-spacing: 0.1em;
  color: var(--ink-dim);
}
.st-tab.active { color: #fff; border-color: var(--c); box-shadow: var(--pixel-edge), 0 0 0 2px var(--c), 0 0 18px var(--c); }
.st-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr)); gap: 12px; overflow-y: auto; padding-right: 6px; }
.st-card {
  background: linear-gradient(180deg, #15101e, #0a0612);
  border: 2px solid #000; box-shadow: var(--pixel-edge);
  padding: 12px; display: flex; flex-direction: column; gap: 6px;
}
.st-card.active-skill { border-color: var(--accent); }
.st-card.maxed { opacity: 0.75; }
.st-card.locked { opacity: 0.45; }
.st-card-h { display: flex; align-items: center; gap: 8px; }
.st-icon { font-size: 22px; filter: drop-shadow(0 0 8px currentColor); }
.st-name { font-family: 'Cinzel', serif; font-weight: 800; font-size: 12px; flex: 1; letter-spacing: 0.05em; }
.st-lv { font-family: 'VT323', monospace; color: var(--rune); font-size: 14px; }
.st-desc { font-family: 'VT323', monospace; font-size: 15px; color: var(--ink-dim); min-height: 32px; }
.st-tag {
  align-self: flex-start; padding: 1px 6px; background: var(--accent); color: #000;
  font-family: 'VT323', monospace; font-size: 11px; letter-spacing: 0.2em;
}
.st-pips { display: flex; gap: 3px; }
.st-pip { width: 14px; height: 6px; background: #00000099; border: 1px solid #000; }
.st-pip.on { background: var(--c); box-shadow: 0 0 6px var(--c); }
.st-card button { padding: 6px 10px; font-size: 11px; }
.st-maxed { color: var(--accent-2); font-family: 'VT323', monospace; letter-spacing: 0.2em; text-align: center; }
.st-locked { color: var(--ink-dim); font-family: 'VT323', monospace; font-size: 11px; }

/* Weaponsmith */
.forge-panel, .shop-panel {
  width: min(1100px, 96vw); max-height: 88vh;
  background: linear-gradient(180deg, #2a0f1a, #07060c);
  border: 2px solid #000; box-shadow: 0 0 0 2px #ff7a1a44, 0 30px 60px #000;
  padding: 20px; display: flex; flex-direction: column;
  overflow-y: auto;
}
.shop-panel { background: linear-gradient(180deg, #0f1e2a, #07060c); box-shadow: 0 0 0 2px #ffd16644, 0 30px 60px #000; }
.forge-header { display: flex; align-items: center; gap: 14px; padding-bottom: 10px; border-bottom: 1px dashed #ffffff22; margin-bottom: 12px; }
.forge-title { font-family: 'Cinzel', serif; font-weight: 800; font-size: 22px; color: var(--accent); letter-spacing: 0.15em; flex: 1; }
.forge-gold { font-family: 'VT323', monospace; color: var(--accent-2); font-size: 22px; letter-spacing: 0.2em; }
.forge-weapons { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.forge-wch {
  width: 76px; padding: 8px;
  background: #0e0816; border: 2px solid #000; box-shadow: var(--pixel-edge);
  text-align: center; cursor: pointer;
  font-family: 'VT323', monospace; color: var(--ink);
}
.forge-wch.sel { border-color: var(--accent); box-shadow: var(--pixel-edge), 0 0 0 2px #ff7a1a, 0 0 16px #ff7a1a88; }
.forge-name { font-family: 'Cinzel', serif; font-weight: 800; font-size: 18px; color: var(--accent-2); letter-spacing: 0.1em; }
.forge-desc { font-family: 'VT323', monospace; color: var(--ink-dim); font-size: 15px; margin-bottom: 10px; }
.forge-parts { display: flex; flex-direction: column; gap: 10px; }
.forge-part { background: #0e0816; border: 2px solid #000; box-shadow: var(--pixel-edge); padding: 10px; }
.forge-part-h { font-family: 'Cinzel', serif; font-weight: 800; font-size: 13px; margin-bottom: 8px; letter-spacing: 0.05em; }
.forge-tiers { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 6px; }
.forge-tier { background: #0a0612; border: 2px solid #000; box-shadow: var(--pixel-edge); padding: 6px 8px; cursor: pointer; color: var(--ink); }
.forge-tier.owned { color: var(--accent-2); border-color: var(--accent-2); }
/* The tier just bought punches instead of silently flipping to "owned" —
   the purchase toast covers the confirmation, this covers the button
   actually reacting to being clicked. */
.forge-tier.just-bought { animation: forgeTierBuy 420ms cubic-bezier(.2,1.4,.3,1) both; }
@keyframes forgeTierBuy {
  0%   { transform: scale(1); box-shadow: var(--pixel-edge); }
  35%  { transform: scale(1.14); box-shadow: 0 0 0 2px var(--accent-2), 0 0 16px var(--accent-2); }
  100% { transform: scale(1); box-shadow: var(--pixel-edge); }
}

/* Shop / Chests */
.chest-row { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr)); gap: 12px; }
.chest-card {
  background: linear-gradient(180deg, #1a1226, #0a0612);
  border: 2px solid #000; box-shadow: var(--pixel-edge), 0 6px 0 #000;
  padding: 14px; text-align: center;
}
.chest-icon { font-size: 56px; filter: drop-shadow(0 0 16px #ffd16699); margin: 8px 0; }
.chest-name { font-family: 'Cinzel', serif; font-weight: 800; color: var(--accent-2); letter-spacing: 0.1em; margin-bottom: 6px; }
.chest-info { font-family: 'VT323', monospace; font-size: 13px; margin-bottom: 8px; }
.chest-opening {
  display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 60px;
}
.chest-anim {
  font-size: 96px;
  animation: chestShake 0.3s ease-in-out infinite;
  filter: drop-shadow(0 0 30px var(--accent-2));
}
@keyframes chestShake {
  0%,100% { transform: rotate(-6deg) scale(1); }
  50% { transform: rotate(6deg) scale(1.05); }
}
.chest-text { font-family: 'Cinzel', serif; font-weight: 800; font-size: 28px; color: var(--accent-2); letter-spacing: 0.3em; animation: pulse 0.6s ease-in-out infinite; }
.chest-result-title { font-family: 'Cinzel', serif; font-weight: 800; font-size: 22px; text-align: center; color: var(--accent-2); letter-spacing: 0.3em; margin-bottom: 14px; }
.chest-result { padding: 14px; }
.drop-row { display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; }
.drop-item.card { width: 200px; min-height: 260px; }
/* Compact equip mini-card — NOT using .card to avoid mobile breakpoint overrides */
.equip-mini {
  width: 110px; min-height: 80px;
  background: linear-gradient(180deg, #16121f 0%, #0a0612 100%);
  border: 2px solid #000;
  border-left: 3px solid var(--rar, #333);
  padding: 8px 6px;
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  text-align: center; flex-shrink: 0;
}
.equip-mini.r-common    { --rar: #9a8fa6; }
.equip-mini.r-uncommon  { --rar: #4dff91; }
.equip-mini.r-rare      { --rar: #4dc4ff; }
.equip-mini.r-epic      { --rar: #b362ff; }
.equip-mini.r-legendary { --rar: #ff7a1a; box-shadow: 0 0 12px #ff7a1a66; }
.equip-mini.r-mythical  { --rar: #ff3146; box-shadow: 0 0 16px #ff314666; }

.inv-section { margin-top: 16px; }
.equip-row { display: flex; gap: 10px; flex-wrap: wrap; }
.equip-slot { display: flex; flex-direction: column; gap: 4px; align-items: center; }
.inv-row { display: flex; gap: 8px; flex-wrap: wrap; }

/* Stats grid */
.stats-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr)); gap: 10px; }
.stat-cell {
  background: linear-gradient(180deg, #15101e, #0a0612);
  border: 2px solid #000; box-shadow: var(--pixel-edge);
  padding: 12px 14px;
}
.stat-lbl { font-family: 'VT323', monospace; color: var(--ink-dim); font-size: 14px; letter-spacing: 0.2em; }
.stat-val { font-family: 'Cinzel', serif; font-weight: 800; color: var(--accent-2); font-size: 22px; margin-top: 2px; }
.stats-bars {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 0 0 14px;
  padding: 12px 14px;
  background: linear-gradient(180deg, #15101e, #0a0612);
  border: 2px solid #000;
  box-shadow: var(--pixel-edge);
}
.stat-bar-row {
  display: grid;
  grid-template-columns: minmax(0, 7.5em) minmax(0, 1fr) 2.4em;
  gap: 8px;
  align-items: center;
}
.stat-bar-l {
  font-family: 'VT323', monospace;
  font-size: 14px;
  letter-spacing: 0.08em;
  color: var(--ink-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stat-bar-track {
  height: 8px;
  background: #07060c;
  border: 1px solid #ffffff14;
  overflow: hidden;
}
.stat-bar-track i { display: block; height: 100%; }
.stat-bar-n {
  font-family: 'VT323', monospace;
  font-size: 15px;
  color: #e9f4ff;
  text-align: right;
}

/* Mobile controls */
.joy {
  position: fixed; bottom: 30px;
  width: 140px; height: 140px;
  background: radial-gradient(circle, #00000088 0%, #00000022 70%);
  border: 2px solid #ffffff22;
  border-radius: 50%;
  z-index: 4;
  display: flex; align-items: center; justify-content: center;
  touch-action: none;
  pointer-events: auto;
}
.joy-l { left: 20px; }
.joy-r { right: 20px; }
.joy-stick {
  width: 60px; height: 60px;
  background: radial-gradient(circle, #4dc4ffaa, #4dc4ff44);
  border: 2px solid #fff8;
  border-radius: 50%;
  box-shadow: 0 0 20px #4dc4ff88;
  transition: transform 60ms;
}
.touch-btn {
  position: fixed;
  width: 64px; height: 64px;
  border-radius: 50%;
  font-size: 26px;
  padding: 0;
  z-index: 4;
  display: flex; align-items: center; justify-content: center;
}
.touch-reload { right: 170px; bottom: 50px; }
.touch-dash { right: 170px; bottom: 130px; border-color: #4dffd4; box-shadow: 0 0 0 2px #000, 0 0 0 3px #4dffd4, 0 0 24px #4dffd488; }

@media (hover: none) and (pointer: coarse) {
  .help { display: none; }
}

/* Dopamine Level Up */
.lvl-burst {
  position: absolute;
  top: 50%; left: 50%;
  width: min(800px, 100vw); height: min(800px, 100vw);
  margin-top: calc(min(-400px, -50vw));
  margin-left: calc(min(-400px, -50vw));
  pointer-events: none;
  animation: spinBurst 8s linear infinite;
  z-index: -1;
}
.lvl-ray {
  position: absolute;
  left: 50%; top: 50%;
  width: 4px; height: 50%;
  background: linear-gradient(180deg, transparent, #ffd16644, transparent);
  transform-origin: 50% 0%;
  margin-left: -2px;
}
@keyframes spinBurst { to { transform: rotate(360deg); } }

.levelup-title {
  font-size: clamp(40px, 9vw, 84px) !important;
  background: linear-gradient(180deg, #fff, #ffd166 40%, #ff7a1a 70%, #b51d28);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  text-shadow: 0 0 40px #ff7a1aaa;
  animation: lvlPunch 600ms cubic-bezier(.2,.9,.3,1.4) both, pulse 1.4s ease-in-out 600ms infinite;
  letter-spacing: 0.1em;
  text-align: center;
  margin: 0 auto;
}
@keyframes lvlPunch {
  0% { transform: scale(0.2) rotate(-15deg); opacity: 0; }
  60% { transform: scale(1.3) rotate(8deg); opacity: 1; }
  100% { transform: scale(1) rotate(0); opacity: 1; }
}
.levelup-mega {
  font-family: 'VT323', monospace;
  font-size: 28px;
  color: var(--rune);
  letter-spacing: 0.5em;
  margin-bottom: 6px;
  text-shadow: 0 0 16px #4dffd488;
}
.card-shine {
  position: absolute; inset: 0;
  background: linear-gradient(120deg, transparent 30%, #ffffff22 50%, transparent 70%);
  pointer-events: none;
  animation: shine 2.4s linear infinite;
}
@keyframes shine {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

/* Intro Dialogue */
.intro-overlay {
  position: fixed; inset: 0;
  background:
    radial-gradient(ellipse at center, #1a0f2a 0%, #000 70%),
    repeating-linear-gradient(0deg, #0000 0 2px, #ffffff05 2px 3px);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  z-index: 50; padding: 40px;
  text-align: center; gap: 20px; cursor: pointer;
}
.intro-aida {
  font-size: 120px;
  color: var(--rune);
  filter: drop-shadow(0 0 40px #4dffd4cc);
  animation: pulse 1.6s ease-in-out infinite;
}
.intro-name {
  font-family: 'Cinzel', serif; font-weight: 800;
  font-size: 28px; color: var(--eldritch);
  letter-spacing: 0.4em;
  text-shadow: 0 0 20px #b362ff88;
}
.intro-text {
  font-family: 'VT323', monospace;
  font-size: 26px; color: var(--ink);
  max-width: 720px;
  letter-spacing: 0.04em;
  line-height: 1.4;
}
.intro-caret { color: var(--rune); animation: blink 0.7s steps(2) infinite; }
@keyframes blink { to { opacity: 0; } }
.intro-skip {
  margin-top: 22px;
  font-family: 'VT323', monospace; font-size: 14px;
  color: var(--ink-dim); letter-spacing: 0.3em;
}

/* ============== ITER 4 UI ============== */
.active-bar {
  position: absolute; bottom: 100px; left: 50%; transform: translateX(-50%);
  display: flex; gap: 10px;
  z-index: 4; pointer-events: auto;
}
.skill-btn {
  position: relative;
  width: 64px; height: 64px;
  background: #0a0612cc;
  border: 2px solid #000;
  box-shadow: var(--pixel-edge), 0 0 14px #0008;
  display: flex; align-items: center; justify-content: center;
  padding: 0; overflow: hidden;
  cursor: pointer;
}
.skill-btn.ready { border-color: var(--accent); box-shadow: var(--pixel-edge), 0 0 0 2px #ff7a1a, 0 0 16px #ff7a1a99; }
.skill-icon { font-size: 32px; filter: drop-shadow(0 0 6px currentColor); }
.skill-key { position: absolute; top: 2px; left: 4px; font-family: 'VT323', monospace; font-size: 11px; color: var(--accent-2); }
.skill-cd { position: absolute; left: 0; right: 0; bottom: 0; background: #000a; pointer-events: none; }
.skill-cd-num { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-family: 'Cinzel', serif; font-weight: 800; font-size: 20px; color: #fff; pointer-events: none; }

/* Slot machine reel */
.slot-reel {
  width: 280px !important; height: 320px !important;
  margin: 0 auto;
  display: flex !important; flex-direction: column; align-items: center; justify-content: center; gap: 8px;
  transition: box-shadow 200ms;
}
.slot-reel.spinning { animation: slotShake 0.1s linear infinite; }
@keyframes slotShake { 0%,100% { transform: translateY(-2px); } 50% { transform: translateY(2px); } }

/* Reveal cells */
.reveal-cell {
  background: #0e0816; border: 2px solid var(--accent-2);
  box-shadow: var(--pixel-edge), 0 0 18px #ffd16644;
  padding: 12px; min-width: 120px; text-align: center;
  display: flex; flex-direction: column; gap: 4px;
  animation: cardIn 380ms cubic-bezier(.2,.9,.3,1.4) both;
}

/* Milestone bar */
.milestone-bar {
  display: flex; gap: 6px; overflow-x: auto; padding: 8px 0;
  scrollbar-width: thin;
}
.ms-pip {
  flex: 0 0 auto;
  width: 80px; padding: 8px 4px;
  background: #0a0612; border: 2px solid #000;
  box-shadow: var(--pixel-edge);
  text-align: center; cursor: pointer;
  font-family: 'VT323', monospace;
}
.ms-pip.reached { border-color: var(--accent); box-shadow: var(--pixel-edge), 0 0 0 1px #ff7a1a88, 0 0 12px #ff7a1a55; }
.ms-pip.claimed { opacity: 0.55; }
.ms-lvl { font-size: 14px; color: var(--accent-2); letter-spacing: 0.2em; }
.ms-rwd { font-size: 11px; color: var(--ink); line-height: 1.2; margin: 4px 0; }
.ms-status { font-size: 11px; color: var(--rune); letter-spacing: 0.2em; }
.ms-status.pulse { animation: pulse 1s ease-in-out infinite; color: var(--accent); }

/* Active skill loadout slots */
.loadout-row { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.loadout-slot {
  width: 90px; height: 110px;
  background: #0a0612; border: 2px solid #000;
  box-shadow: var(--pixel-edge);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  font-family: 'VT323', monospace; color: var(--ink-dim);
  position: relative;
}
.loadout-slot.eq { border-color: var(--accent); box-shadow: var(--pixel-edge), 0 0 0 2px #ff7a1a; }
.ls-key { position: absolute; top: 4px; left: 6px; color: var(--accent-2); font-size: 14px; }
.ls-icon { font-size: 40px; filter: drop-shadow(0 0 8px currentColor); }
.ls-name { font-size: 11px; color: var(--ink); text-align: center; padding: 0 4px; }

/* Parts workshop */
.parts-slots { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(140px, 100%), 1fr)); gap: 8px; }
.part-slot { background: #0e0816; border: 2px solid #000; box-shadow: var(--pixel-edge); padding: 8px; }
.ps-name { font-family: 'VT323', monospace; color: var(--ink-dim); font-size: 13px; letter-spacing: 0.2em; margin-bottom: 4px; }
.ps-empty { color: var(--ink-dim); font-style: italic; font-size: 12px; }
.part-chip {
  background: linear-gradient(180deg, #15101e, #0a0612);
  border: 2px solid #000;
  box-shadow: var(--pixel-edge), 0 0 0 2px var(--rar);
  padding: 8px; min-width: 130px;
  font-family: 'VT323', monospace;
}
.part-chip.r-common { --rar: #9a8fa6; }
.part-chip.r-uncommon { --rar: #4dff91; box-shadow: var(--pixel-edge), 0 0 0 1px var(--rar); }
.part-chip.r-rare { --rar: #ffd166; }
.part-chip.r-epic { --rar: #b362ff; }
.part-chip.r-common   { --rar: #9a8fa6; }
.part-chip.r-uncommon { --rar: #4dff91; box-shadow: var(--pixel-edge), 0 0 0 1px var(--rar); }
.part-chip.r-magic    { --rar: #4dc4ff; box-shadow: var(--pixel-edge), 0 0 0 1px var(--rar); }
