.part-chip.r-mythical  { --rar: #ff3146; box-shadow: var(--pixel-edge), 0 0 0 2px #ff3146, 0 0 20px #ff3146, 0 0 38px rgba(255,49,70,0.5); animation: mythPulse 600ms ease-in-out infinite alternate; }
@keyframes mythPulse { from { box-shadow: var(--pixel-edge), 0 0 0 2px #ff3146, 0 0 14px #ff3146; } to { box-shadow: var(--pixel-edge), 0 0 0 2px #ff3146, 0 0 28px #ff3146, 0 0 50px rgba(255,49,70,0.45); } }

/* Settings rows */
