}
.camp-tab.active { border-left-color: var(--accent); }


/* ============================================================
   GAME OVER — modern reward summary
   ============================================================ */
.gameover.go-modern {
  width: min(560px, 94vw);
  max-height: min(92vh, 800px);
  overflow-y: auto;
  padding: 26px 26px 22px;
  background: linear-gradient(180deg, #1a0d12 0%, #07060c 100%);
  border: 2px solid #000;
  box-shadow: 0 0 0 2px #b51d2888, 0 30px 80px #000c, inset 0 1px 0 #ffffff10;
  text-align: center;
  position: relative;
  animation: goPop 360ms cubic-bezier(.2,.9,.3,1.4) both;
}
.gameover.go-modern.is-victory {
  background: linear-gradient(180deg, #0f1f1a 0%, #07060c 100%);
  box-shadow: 0 0 0 2px #4dffd488, 0 30px 80px #000c, inset 0 1px 0 #ffffff10;
}
@keyframes goPop {
  0%   { transform: scale(0.85); opacity: 0; }
  60%  { transform: scale(1.04); opacity: 1; }
  100% { transform: scale(1); }
}
.go-title {
  font-family: 'Cinzel', serif; font-weight: 800;
  font-size: clamp(34px, 7vw, 54px);
  background: linear-gradient(180deg, #ff5566, #b51d28);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  letter-spacing: 0.12em; margin-bottom: 4px;
  text-shadow: 0 0 30px #b51d2855;
}
.is-victory .go-title {
  background: linear-gradient(180deg, #ffd166, #4dffd4);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.go-sub {
  font-family: 'VT323', monospace;
  color: var(--ink-dim);
  letter-spacing: 0.18em;
  font-size: 14px;
  margin-bottom: 18px;
}
.go-stats-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 18px;
}
.go-stat {
  display: flex; flex-direction: column; align-items: center;
  padding: 10px 4px;
  background: #00000055;
  border: 1px solid #ffffff10;
  border-bottom: 2px solid var(--accent);
}
.go-stat span {
  font-family: 'VT323', monospace; font-size: 12px;
  letter-spacing: 0.2em; color: var(--ink-dim);
}
.go-stat b {
  font-family: 'Cinzel', serif; font-weight: 800;
  font-size: 22px; color: #fff; margin-top: 2px;
}
.go-profile-xp {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 16px; padding: 8px 12px;
  background: #00000044; border: 1px solid #ffffff12;
}
.go-profile-rank {
  font-family: 'VT323', monospace; font-size: 13px; letter-spacing: 0.12em;
  color: var(--rune, #4dffd4); flex: 0 0 auto;
}
.go-profile-bar {
  flex: 1 1 auto; height: 8px; background: #0a0612;
  border: 1px solid #000; overflow: hidden;
}
.go-profile-fill {
  height: 100%;
  background: linear-gradient(90deg, #4dffd4, #b6ffec);
  box-shadow: 0 0 10px #4dffd488;
  transition: width 1.1s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.go-profile-gain {
  font-family: 'VT323', monospace; font-size: 13px; color: #6dff9e;
  text-shadow: 0 0 8px #6dff9e66; flex: 0 0 auto;
}
.go-section-title {
  font-family: 'VT323', monospace;
  letter-spacing: 0.3em;
  font-size: 13px;
  color: var(--accent-2);
  text-align: left;
  margin: 4px 0 8px 2px;
  border-bottom: 1px solid #ffffff15;
  padding-bottom: 4px;
}
.go-rewards {
  display: flex; flex-direction: column; gap: 6px;
  margin-bottom: 14px;
}
.go-reward-row {
  display: grid; grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: center;
  padding: 8px 12px;
  background: #00000044;
  border-left: 3px solid var(--accent-2);
  font-family: 'VT323', monospace;
}
.go-reward-icon { font-size: 18px; }
.go-reward-label { text-align: left; color: var(--ink); letter-spacing: 0.05em; font-size: 16px; }
.go-reward-val { color: #ffd166; font-weight: 800; font-size: 18px; }
.go-badges {
  display: flex; flex-wrap: wrap; gap: 8px; justify-content: center;
  margin: 6px 0 16px;
}
.go-badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 12px;
  background: linear-gradient(180deg, #2a1e0a, #1a1206);
  border: 1px solid #ffd16699;
  box-shadow: 0 0 12px #ffd16644;
  font-family: 'VT323', monospace; font-size: 13px;
  letter-spacing: 0.18em;
  color: #ffd166;
  animation: goBadgeIn 400ms cubic-bezier(.2,.9,.3,1.4) both;
}
@keyframes goBadgeIn {
  from { transform: scale(0.6); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}
.go-actions {
  display: flex; gap: 10px; justify-content: center;
  margin-top: 8px; flex-wrap: wrap;
}
.go-btn {
  flex: 1 1 0; min-width: 100px;
  padding: 12px 14px;
  font-family: 'Cinzel', serif; font-weight: 800;
  letter-spacing: 0.18em;
  font-size: 13px;
  border: 2px solid #000;
  cursor: pointer;
  transition: transform 100ms, box-shadow 100ms;
}
.go-btn:hover { transform: translateY(-2px); }
.go-btn-ghost { background: #1a1226; color: var(--ink-dim); }
.go-btn-camp { background: linear-gradient(180deg, #244a3a, #112218); color: #4dffd4; box-shadow: 0 4px 0 #000, 0 0 14px #4dffd455; }
.go-btn-retry { background: linear-gradient(180deg, #ff7a1a, #b51d28); color: #fff; box-shadow: 0 4px 0 #000, 0 0 22px #ff7a1a99; }

@media (max-width: 480px) {
  .gameover.go-modern { padding: 18px 16px 14px; }
  .go-stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .go-stat b { font-size: 18px; }
  .go-reward-label { font-size: 14px; }
  .go-reward-val { font-size: 15px; }
  .go-actions { gap: 6px; }
  .go-btn { font-size: 11px; padding: 10px 8px; min-width: 0; }
