/* ============================================================
   HUD ITER 9 — centered timer, between-joystick skills, rounded HP
   ============================================================ */

/* Dash gesture ring around left joystick */
.joy-dash-ring {
  position: absolute; inset: -6px;
  border-radius: 50%;
  pointer-events: none;
  display: flex; align-items: center; justify-content: center;
  font-family: 'VT323', monospace; font-size: 22px; z-index: 1;
}
.joy-dash-ring.ready  { border: 2px solid #4dffd4; box-shadow: 0 0 18px #4dffd488, inset 0 0 8px #4dffd444; color: #4dffd4; animation: dashPulse 1.4s ease-in-out infinite; }
.joy-dash-ring.cooldown { border: 2px dashed #777; color: #888; opacity: 0.65; }
.joy-dash-ring span { position: absolute; top: -22px; background: #06040a; padding: 1px 8px; border: 1px solid #4dffd488; border-radius: 8px; font-size: 12px; }
.joy-dash-ring.cooldown span { border-color: #555; }
@keyframes dashPulse {
  0%, 100% { box-shadow: 0 0 14px #4dffd455, inset 0 0 6px #4dffd433; }
  50%      { box-shadow: 0 0 26px #4dffd488, inset 0 0 12px #4dffd466; }
}

/* Top: timer + wave centered horizontally */
.hud-top {
  position: fixed; top: 14px; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center;
  gap: 4px; z-index: 30; pointer-events: none;
}
.hud-timer, .hud-wave, .hud-level { text-align: center; }
.hud-xpbar { width: min(680px, 70vw); max-width: 90vw; }
.hud-boss-bar {
  position: fixed !important;
  top: 0 !important; left: 50% !important; transform: translateX(-50%) !important;
  width: min(700px, 88vw);
  background: linear-gradient(180deg, #1a0608ee, #0a040a99);
  border-bottom: 2px solid #ff7a1a44;
  padding: 4px 12px 6px;
  z-index: 32;
  pointer-events: none;
}
.hud-boss-name { font-family: 'VT323', monospace; color: #ff7a1a; letter-spacing: 0.3em; text-align: center; font-size: 18px; }
.hud-boss-bar-track { height: 10px; background: #00000099; border: 1px solid #000; box-shadow: inset 0 0 0 1px #ffffff10; }
.hud-boss-bar-fill { height: 100%; background: linear-gradient(90deg,#ff7a1a,#b51d28); transition: width 200ms; }
/* Push the timer/wave block down below the boss bar so they never overlap */
.hud-top.boss-active { top: 66px; }
.weapon-strip {
  position: fixed !important;
  top: 105px !important; left: 14px !important;
  right: auto !important; bottom: auto !important;
  transform: none !important;
  display: flex !important; flex-direction: row !important;
  flex-wrap: wrap;
  gap: 4px;
  max-width: 260px;
  z-index: 30;
}
/* When boss is active, push weapon strip below boss bar */
.boss-active ~ .weapon-strip, .hud-boss-bar + * .weapon-strip {
  top: 160px !important;
}
.weapon-chip {
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,0,0,0.55);
  border: 1px solid #ffffff15;
  font-size: 24px;
  position: relative;
  border-radius: 4px;
}
.weapon-chip .lv {
  position: absolute; bottom: -2px; right: 0;
  background: #06040a; color: var(--accent);
  font-size: 9px; padding: 0 3px;
  border: 1px solid #ffffff15;
}

/* Overflow skills (3+) → top-right vertical column */
.active-bar-overflow {
  position: fixed !important;
  top: 90px !important; right: 14px !important;
  left: auto !important; bottom: auto !important;
  transform: none !important;
  display: flex !important; flex-direction: column !important;
  gap: 6px; z-index: 30;
}

/* ---- PROFILE LEVEL-UP OVERLAY ---- */
.lu-overlay {
  position: fixed; inset: 0; z-index: 200;
  background:
    radial-gradient(ellipse 70% 55% at 50% 42%, rgba(18, 48, 56, 0.55), transparent 62%),
    radial-gradient(ellipse 90% 80% at 50% 100%, rgba(4, 18, 28, 0.9), #02040a 70%),
    #030712;
  backdrop-filter: blur(8px);
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.lu-overlay::before {
  content: '';
  position: absolute; inset: -20%;
  pointer-events: none;
  background:
    repeating-conic-gradient(from 0deg at 50% 48%,
      rgba(255, 209, 102, 0.0) 0deg 7deg,
      rgba(255, 209, 102, 0.11) 8deg 9deg,
      rgba(255, 209, 102, 0.0) 10deg 22deg);
  mask-image: radial-gradient(circle at 50% 48%, #000 0 18%, transparent 58%);
  -webkit-mask-image: radial-gradient(circle at 50% 48%, #000 0 18%, transparent 58%);
  opacity: 0.85;
}
.lu-confetti {
  position: absolute; top: -14px;
  width: 9px; height: 12px; border-radius: 2px;
  animation: luFall 2.4s ease-in infinite;
}
@keyframes luFall {
  0%   { transform: translateY(0) rotate(0deg); opacity: 1; }
  100% { transform: translateY(108vh) rotate(540deg); opacity: 0.15; }
}
.lu-laser {
  position: absolute; top: 50%; left: 50%;
  width: 60vw; height: 2px;
  transform-origin: left center;
  background: linear-gradient(90deg, #ffd16688 0%, transparent 100%);
  animation: luLaserPulse 1.8s ease-in-out infinite alternate;
  pointer-events: none;
}
@keyframes luLaserPulse { from { opacity: 0.15; } to { opacity: 0.55; } }
.lu-card {
  position: relative; z-index: 10;
  background: linear-gradient(160deg, #0e242cee, #080c16ee);
  border: 2px solid #4fe0e888;
  box-shadow: 0 0 50px #4fe0e833, 0 0 120px #ffd16622;
  padding: 30px 36px 24px; min-width: 280px; max-width: 360px;
  text-align: center;
  animation: luPop 0.4s cubic-bezier(0.22,1,0.36,1);
}
@keyframes luPop { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
.lu-avatar { font-size: 78px; line-height: 1; margin-bottom: 6px; display: block; animation: luBounce 1.4s ease-in-out infinite alternate; }
@keyframes luBounce { from { transform: scale(1) rotate(-3deg); } to { transform: scale(1.1) rotate(3deg); } }
.lu-title { font-family: 'VT323', monospace; font-size: 42px; color: #7fe8ff; letter-spacing: 0.35em; text-shadow: 0 0 22px #4fe0e8, 0 0 50px #4fe0e844; }
.lu-rank  { font-family: 'VT323', monospace; font-size: 22px; color: #4dffd4; letter-spacing: 0.22em; margin-bottom: 14px; }
.lu-xp    { height: 7px; background: #00000066; border: 1px solid #ffffff18; margin-bottom: 20px; overflow: hidden; border-radius: 0; }
.lu-xp-fill { height: 100%; background: linear-gradient(90deg, #4dffd4, #ffd166, #ff7a1a); animation: luXp 2s ease-out forwards; }
@keyframes luXp { 0% { width: 0%; } 68% { width: 100%; } 70% { width: 0%; } 100% { width: 60%; } }
.lu-rwd { font-family: 'VT323', monospace; font-size: 24px; color: #ffd166; letter-spacing: 0.15em; }
.lu-collect {
  font-family: 'VT323', monospace; font-size: 22px; letter-spacing: 0.22em;
  padding: 11px 22px; background: #0a1618; border: 2px solid #e0b24a; color: #ffe08a;
  cursor: pointer; transition: background 0.15s, box-shadow 0.15s;
  width: 100%;
  box-shadow: 0 0 18px rgba(224, 178, 74, 0.28);
}
.lu-collect:hover { background: #122428; box-shadow: 0 0 26px rgba(79, 224, 232, 0.35); }
/* end Level-Up Overlay */

/* ---------- MAPS PANEL ---------- */
.maps-grid {
  display: flex; flex-direction: column; gap: 18px;
  padding: 4px 0;
}
.map-stage-card {
  background: #0e0816ee;
  border: 1px solid #ffffff18;
  border-radius: 0;
  padding: 14px 16px;
  box-shadow: var(--pixel-edge);
  transition: border-color 0.2s, box-shadow 0.2s;
}
.map-stage-card.locked { opacity: 0.55; }
.map-stage-card.complete { border-style: solid; }
.map-stage-head {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 6px;
}
.map-stage-name { font-family: 'VT323', monospace; font-size: 20px; letter-spacing: 0.15em; }
.map-stage-desc { font-size: 12px; color: var(--ink-dim); margin-bottom: 10px; line-height: 1.5; }
.map-stage-lock { font-family: 'VT323', monospace; color: #ff7a1a99; font-size: 13px; letter-spacing: 0.2em; }
.map-nodes { display: flex; flex-direction: column; gap: 8px; }
.map-node {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-items: center;
  gap: 2px 8px;
  padding: 8px 10px;
  background: #00000044;
  border: 1px solid #ffffff0e;
}
.map-node.done { opacity: 0.6; background: #00000022; }
.map-node.node-locked { opacity: 0.45; }
.node-diff { font-family: 'VT323', monospace; font-size: 12px; letter-spacing: 0.15em; grid-row: 1; }
.node-name { font-size: 13px; font-weight: 800; color: var(--ink); grid-row: 1; }
.node-meta { font-size: 11px; color: var(--ink-dim); grid-row: 2; grid-column: 2; }
.node-rwd  { font-family: 'VT323', monospace; font-size: 13px; color: #ffd166; grid-row: 2; grid-column: 3; text-align: right; }
.map-node button { grid-row: 1 / 3; grid-column: 3; font-family: 'VT323', monospace; font-size: 14px; letter-spacing: 0.15em; padding: 5px 10px; background: #00000066; border-width: 1px; }
.map-node button:disabled { cursor: not-allowed; }
.node-connector {
  text-align: center; font-size: 11px; line-height: 1;
  margin: 2px auto; width: 2px; height: 12px;
  opacity: 0.7;
  pointer-events: none;
}
.map-stage-done, .map-node-cleared {
