/* ============================================================
   CARD SHOP — 3-reel slot machine animations
   ============================================================ */
.cs-modal { padding-bottom: 18px; }
.slot-frame {
  position: relative;
  background: linear-gradient(180deg, #0e2429 0%, #071216 100%);
  border: 3px solid #000;
  box-shadow:
    inset 0 0 0 2px #ffd16699,
    inset 0 12px 24px #0008,
    0 8px 0 #000,
    0 0 24px #ffd16633;
  padding: 16px 14px 14px;
  margin: 0 auto;
  max-width: 460px;
  transition: box-shadow 220ms, border-color 220ms;
}
.slot-frame.cs-shake { animation: csShake 90ms infinite; }
@keyframes csShake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-1px) translateY(1px); }
  50% { transform: translateX(1px); }
  75% { transform: translateX(0) translateY(-1px); }
}
.slot-frame.cs-jackpot {
  border-color: #ffd166;
  box-shadow:
    inset 0 0 0 2px #ffd166,
    inset 0 12px 24px #0008,
    0 8px 0 #000,
    0 0 60px #ffd16699,
    0 0 120px #ff7a1a44;
  animation: csJackpot 600ms ease-out;
}
@keyframes csJackpot {
  0%   { transform: scale(0.95); }
  40%  { transform: scale(1.08); }
  100% { transform: scale(1); }
}
.slot-window {
  display: grid;
  grid-template-columns: repeat(3, minmax(80px, 1fr));
  gap: 8px;
  background: #06040a;
  border: 2px solid #000;
  padding: 8px;
  box-shadow: inset 0 0 0 1px #ffffff10;
  margin: 0 auto 12px;
  width: 100%;
  max-width: 420px;
}
.slot-cell {
  background: linear-gradient(180deg, #141826 0%, #06080f 100%);
  border: 1px solid #ffffff15;
  min-height: 100px;
  height: 100px;
  width: 100%;
  display: flex; align-items: center; justify-content: center;
  position: relative;
  overflow: hidden;
}
.slot-cell.spinning .slot-icon {
  animation: csReel 70ms infinite linear;
  filter: blur(1.5px);
}
.slot-cell.stopped .slot-icon {
  animation: csStop 280ms cubic-bezier(.34, 1.56, .64, 1);
}
.slot-cell.cs-glow {
  box-shadow: 0 0 18px currentColor, inset 0 0 14px #00000080;
}
.slot-cell.cs-glow.rar-common    { color: #9a8fa6; box-shadow: inset 0 0 0 2px #9a8fa6, inset 0 0 14px #00000080, 0 0 14px #9a8fa677; }
.slot-cell.cs-glow.rar-uncommon  { color: #4dff91; box-shadow: inset 0 0 0 2px #4dff91, inset 0 0 14px #00000080, 0 0 18px #4dff91aa; }
.slot-cell.cs-glow.rar-rare      { color: #4dc4ff; box-shadow: inset 0 0 0 2px #4dc4ff, inset 0 0 14px #00000080, 0 0 22px #4dc4ffaa; }
.slot-cell.cs-glow.rar-epic      { color: #b362ff; box-shadow: inset 0 0 0 2px #b362ff, inset 0 0 14px #00000080, 0 0 26px #b362ffaa; }
.slot-cell.cs-glow.rar-legendary { color: #ff7a1a; box-shadow: inset 0 0 0 2px #ff7a1a, inset 0 0 18px #00000080, 0 0 32px #ff7a1add; animation: legPulse 700ms ease-in-out infinite alternate; }
.slot-cell.cs-glow.rar-mythical  { color: #ff3146; box-shadow: inset 0 0 0 2px #ff3146, inset 0 0 20px #00000080, 0 0 40px #ff3146ee; animation: legPulse 500ms ease-in-out infinite alternate; }
@keyframes legPulse {
  from { box-shadow: inset 0 0 0 2px #ffd166, inset 0 0 18px #00000080, 0 0 26px #ffd166aa; }
  to   { box-shadow: inset 0 0 0 2px #fff,    inset 0 0 22px #00000080, 0 0 44px #ffd166ff; }
}
.slot-icon {
  font-size: 54px;
  text-shadow: 0 2px 8px #000a;
}
@keyframes csReel {
  0%   { transform: translateY(-30px); opacity: 0.4; }
  50%  { transform: translateY(0);     opacity: 1; }
  100% { transform: translateY(30px);  opacity: 0.4; }
}
@keyframes csStop {
  0%   { transform: translateY(-26px) scale(0.8); opacity: 0; }
  60%  { transform: translateY(4px)   scale(1.18); opacity: 1; }
  100% { transform: translateY(0)     scale(1); }
}
.cs-status, .cs-result {
