.base-card-top { display: flex; align-items: flex-start; gap: 9px; }
.base-card-name { font-family: 'VT323', monospace; font-size: 17px; color: #eafffb; letter-spacing: 0.05em; }
.base-card-blurb { font-size: 11px; color: #6d8290; font-style: italic; line-height: 1.3; }
.base-card-lvl {
  margin-left: auto; font-family: 'VT323', monospace; font-size: 20px; color: var(--bc);
}
.base-card-lvl i { font-style: normal; font-size: 12px; color: #55707e; }
.base-card-effect { font-family: 'VT323', monospace; font-size: 13px; color: #cfe6de; margin: 7px 0 5px; }
.base-card-none { color: #55707e; }
.base-card-next { color: #6dff9e; }
.base-pips { display: flex; gap: 2px; margin-bottom: 8px; }
.base-pips i { flex: 1; height: 4px; background: #ffffff14; }
