.base-btn.buy { color: #ffd166; border-color: #ffd16644; }
.base-btn.buy:not(:disabled):hover { background: #ffd1661f; border-color: #ffd166; }
.base-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.base-btn.maxlbl { flex: 1; text-align: center; color: #4dff91; border-color: #4dff9144; background: #4dff9114; }

/* ============================================================
   PATROL ENCOUNTER — card battle
   ============================================================ */
.cb-panel {
  width: min(520px, 94vw);
  background: linear-gradient(180deg, #14101c 0%, #06040a 100%);
