}
.cb-card.shown { transform: translateY(-4px) scale(1.04); }
.cb-card-foe.shown { border-color: #ff5566; box-shadow: 0 0 20px rgba(255,85,102,0.35); }
.cb-card-you.shown { border-color: #4dc4ff; box-shadow: 0 0 20px rgba(77,196,255,0.35); }
.cb-power { font-family: 'VT323', monospace; font-size: 34px; color: #f2eaff; }
.cb-vs {
