.cb-hand-power { font-family: 'VT323', monospace; font-size: 21px; color: #ffd166; line-height: 1; }
.cb-hand-desc { font-size: 9.5px; color: #6d5f82; text-align: center; line-height: 1.25; }

/* ── Star Raid mode picker ────────────────────────────────────── */
.raid-modes { display: flex; gap: 7px; margin-bottom: 10px; }
