  border: 1px solid #ffffff1c; background: #ffffff06;
  filter: grayscale(1) brightness(0.5);
}
.camp-chest.won {
  filter: none; border-color: #ffd166;
  box-shadow: 0 0 20px rgba(255,209,102,0.45);
  animation: cardIn 320ms cubic-bezier(.2,.9,.3,1.4) both;
}
.camp-payout-list { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; margin-bottom: 16px; }
.camp-payout-item {
  font-family: 'VT323', monospace; font-size: 13px;
  padding: 3px 8px;
  background: #ffffff0a; border: 1px solid #ffffff1c;
}

/* ── Weapon attachments ───────────────────────────────────────── */
.atc-block { margin-bottom: 16px; }
.atc-head {
  display: flex; justify-content: space-between; align-items: baseline;
  font-family: 'VT323', monospace; font-size: 13px; letter-spacing: 0.16em;
  color: var(--accent-2); margin-bottom: 7px;
}
.atc-sub { font-size: 11px; color: var(--ink-dim); letter-spacing: 0.06em; }
.atc-slots { display: grid; grid-template-columns: repeat(auto-fit, minmax(112px, 1fr)); gap: 6px; }
.atc-slot {
  --ac: #ffffff22;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 8px 5px; cursor: pointer; text-align: center;
  background: linear-gradient(160deg, rgba(20,26,38,0.92), rgba(6,9,15,0.92));
  border: 1px solid var(--ac);
  transition: border-color 0.14s, box-shadow 0.14s, transform 0.08s;
}
.atc-slot:hover { transform: translateY(-1px); }
.atc-slot.filled { box-shadow: inset 0 0 16px color-mix(in srgb, var(--ac) 14%, transparent); }
.atc-slot.open { box-shadow: 0 0 16px color-mix(in srgb, var(--ac) 45%, transparent); border-color: var(--ac); }
.atc-slot-name { font-family: 'VT323', monospace; font-size: 12px; letter-spacing: 0.1em; color: #cfe0ee; }
.atc-slot-fit { font-size: 10px; color: var(--ink-dim); line-height: 1.2; }

.atc-picker {
  margin-top: 7px; padding: 8px;
  background: #ffffff06; border: 1px solid #ffffff16;
  display: flex; flex-direction: column; gap: 5px;
  max-height: 240px; overflow-y: auto;
}
.atc-picker-head { font-size: 11px; color: #6d8290; font-style: italic; margin-bottom: 2px; }
.atc-empty { font-family: 'VT323', monospace; font-size: 12.5px; color: var(--ink-dim); padding: 6px 2px; }
.atc-opt {
  --ac: #9a8fa6;
  display: flex; flex-direction: column; align-items: flex-start; gap: 3px;
  padding: 7px 9px; cursor: pointer; text-align: left;
  background: rgba(255,255,255,0.04);
  border: 1px solid color-mix(in srgb, var(--ac) 40%, transparent);
  border-left-width: 3px;
  transition: background 0.13s, border-color 0.13s;
}
.atc-opt:hover { background: color-mix(in srgb, var(--ac) 12%, transparent); border-color: var(--ac); }
.atc-opt-name { font-family: 'VT323', monospace; font-size: 14px; color: var(--ac); }
.atc-opt-mods { display: flex; flex-wrap: wrap; gap: 4px; }
.atc-opt-mods i {
  font-style: normal; font-family: 'VT323', monospace; font-size: 11px;
  padding: 0 5px; border: 1px solid currentColor;
}
.atc-opt-mods .up { color: #6dff9e; }
.atc-opt-mods .down { color: #ff8a95; }
.atc-opt-mods .elem { color: #c8a0ff; }
.atc-clear { color: #ff8a95; border-color: #ff8a9544; font-family: 'VT323', monospace; font-size: 13px; }

/* ── Gear levelling ───────────────────────────────────────────── */
.gear-parts-bar {
  display: flex; align-items: center; gap: 9px; flex-wrap: wrap;
  padding: 7px 10px; margin-bottom: 10px;
  background: linear-gradient(180deg, rgba(255,209,102,0.08), rgba(0,0,0,0.28));
  border: 1px solid #ffd16633;
  font-family: 'VT323', monospace;
}
.gear-parts-label { font-size: 13px; letter-spacing: 0.16em; color: #ffd166; }
.gear-parts-val { font-size: 17px; color: #fff3c4; }
.gear-parts-hint { font-size: 11.5px; color: var(--ink-dim); margin-left: auto; }
.gear-slot-parts {
  display: flex; flex-wrap: wrap; gap: 6px; width: 100%;
  margin-top: 4px;
}
.gear-slot-part {
  display: inline-flex; align-items: center; gap: 3px;
  font-size: 12px; color: #c8efe8;
  padding: 2px 6px;
  background: linear-gradient(180deg, rgba(80,160,150,0.12), rgba(0,0,0,0.28));
  border: 1px solid rgba(120,210,190,0.22);
}
.gear-cmp-list { margin: 6px 0 10px; display: flex; flex-direction: column; gap: 2px; }
.gear-cmp-vs { font-size: 10px; letter-spacing: 0.12em; color: #6a8a86; }
.gear-cmp {
  display: inline-flex; align-items: center; gap: 4px;
