/* ============================================================
   PET INCUBATOR — rarity-timed hatching, ticks offline
   ============================================================ */
.inc-head {
  display: flex; justify-content: space-between; align-items: baseline;
  font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.18em;
  color: #ff9a4d; margin-bottom: 8px;
}
.inc-slots { font-size: 12px; color: var(--ink-dim); letter-spacing: 0.1em; }
.inc-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(min(150px, 100%), 1fr));
  gap: 10px; margin-bottom: 18px;
}
.inc-slot {
  --rc: #9a8fa6;
  position: relative;
  background: radial-gradient(ellipse at 50% 22%, #1e1030 0%, #0a0520 72%);
  border: 1px solid color-mix(in srgb, var(--rc) 55%, #000);
  border-radius: 8px;
  padding: 12px 10px 10px;
  text-align: center;
  box-shadow: inset 0 0 20px rgba(0,0,0,0.65), 0 3px 10px rgba(0,0,0,0.5);
}
.inc-slot.is-ready {
  border-color: var(--rc);
  box-shadow: inset 0 0 22px color-mix(in srgb, var(--rc) 18%, transparent), 0 0 20px color-mix(in srgb, var(--rc) 45%, transparent);
}
.inc-empty {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 4px; min-height: 118px;
  border-style: dashed; border-color: #ffffff20;
  background: #ffffff05;
}
.inc-empty-mark { font-size: 24px; color: #ffffff2e; line-height: 1; }
.inc-empty-txt { font-family: 'VT323', monospace; font-size: 12px; color: #ffffff35; letter-spacing: 0.1em; }

.inc-egg {
  font-size: 38px; line-height: 1;
  cursor: default;
  display: inline-block;
  filter: grayscale(0.55) brightness(0.75);
  transition: filter 0.2s;
}
/* Ready eggs rock and glow — the cue that this one wants tapping. */
.inc-egg.ready {
  cursor: pointer;
  filter: drop-shadow(0 0 10px var(--rc));
  animation: incRock 1.5s ease-in-out infinite;
}
@keyframes incRock {
  0%, 100% { transform: rotate(-5deg) translateY(0); }
  50%      { transform: rotate(5deg) translateY(-3px); }
}
/* Each successful tap shakes harder and fractures further. */
.inc-egg.crack-1 { animation: incShake 0.28s ease-out; }
.inc-egg.crack-2 { animation: incShake 0.2s ease-out; filter: drop-shadow(0 0 14px var(--rc)) contrast(1.2); }
@keyframes incShake {
  0%, 100% { transform: translateX(0) rotate(0); }
  20% { transform: translateX(-5px) rotate(-9deg); }
  45% { transform: translateX(5px) rotate(8deg); }
  70% { transform: translateX(-3px) rotate(-5deg); }
}
.inc-crack-count {
  display: block; font-family: 'VT323', monospace; font-size: 11px;
  color: var(--rc); letter-spacing: 0.1em;
}
.inc-name { font-family: 'VT323', monospace; font-size: 13px; margin-top: 2px; text-transform: uppercase; }
.inc-ready-txt {
  font-family: 'VT323', monospace; font-size: 12px; color: #4dffd4;
  letter-spacing: 0.12em; margin-top: 4px;
  animation: attrPulse 1.3s ease-in-out infinite;
}
.inc-bar {
  height: 5px; background: #00000088; border: 1px solid #ffffff14;
  margin: 6px 0 3px; overflow: hidden;
}
.inc-fill {
  height: 100%;
  background: linear-gradient(90deg, color-mix(in srgb, var(--rc) 60%, #000), var(--rc));
  box-shadow: 0 0 8px var(--rc);
  transition: width 0.9s linear;
}
.inc-time { font-family: 'VT323', monospace; font-size: 12px; color: var(--ink-dim); }
.inc-btns { display: flex; gap: 4px; margin-top: 6px; }
.inc-btn {
  flex: 1; font-family: 'VT323', monospace; font-size: 11px;
  padding: 3px 4px; cursor: pointer;
  background: #ffffff0d; border: 1px solid #ffffff24; color: var(--ink);
  transition: background 0.14s, border-color 0.14s;
}
.inc-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.inc-btn.inc-gem:not(:disabled):hover  { background: #4dffd41f; border-color: #4dffd4; color: #4dffd4; }
.inc-btn.inc-gold:not(:disabled):hover { background: #ffd1661f; border-color: #ffd166; color: #ffd166; }

.lb-top { border-left-color: #ffd166; box-shadow: inset 0 0 0 1px #ffd16633; }
.lb-rank { font-size: 18px; text-align: center; }
.lb-avatar { width: 26px; height: 26px; border-radius: 50%; object-fit: cover; }
.lb-avatar-fb { display: flex; align-items: center; justify-content: center; background: #1a2740; font-size: 14px; border-radius: 50%; }
.lb-name { font-size: 14px; color: #fff; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lb-meta { display: flex; gap: 4px; margin-top: 2px; }
.lb-badge { font-size: 9px; letter-spacing: 0.15em; padding: 1px 4px; }
.lb-badge-gold { background: #ffd16633; color: #ffd166; border: 1px solid #ffd16688; }
.lb-badge-cyan { background: #4dffd433; color: #4dffd4; border: 1px solid #4dffd488; }
.lb-stat { display: flex; flex-direction: column; align-items: center; }
.lb-stat span { font-size: 9px; color: var(--ink-dim); letter-spacing: 0.18em; }
.lb-stat b { font-size: 14px; color: #fff; }
@media (max-width: 540px) {
  .lb-row { grid-template-columns: 28px 24px minmax(0, 1fr) 44px 36px 44px; gap: 4px; padding: 4px 6px; }
  .lb-name { font-size: 12px; }
  .lb-stat b { font-size: 12px; }
  .lb-stat span { font-size: 8px; }
}



/* ═══════════════════════════════════════════
   CHARACTER PANEL
═══════════════════════════════════════════ */
.char-panel { position: relative; }
.char-rar-bar { display: flex; gap: 6px; margin: 12px 0; justify-content: center; }
.char-rar-step {
  width: 64px; height: 26px;
  display: flex; align-items: center; justify-content: center;
  font-family: 'VT323', monospace; font-size: 13px;
  border-radius: 2px; transition: all 0.3s;
}
.char-lvl-bar { height: 6px; background: #1a1226; border-radius: 2px; margin: 8px 0; overflow: hidden; }
.char-lvl-fill { height: 100%; border-radius: 2px; transition: width 0.5s ease; }
.char-slot-badge { border: 1px solid; padding: 8px 16px; text-align: center; fontFamily: 'VT323'; font-size: 15px; letter-spacing: 0.15em; margin: 10px 0; }
.char-currency { display: flex; gap: 24px; justify-content: center; margin: 10px 0; font-family: 'VT323'; font-size: 20px; }
.char-next-stat { text-align: center; color: var(--ink-dim); font-size: 13px; margin: 6px 0; font-family: 'VT323'; letter-spacing: 0.1em; }
.char-btn {
  display: block; width: 100%; margin-top: 10px; min-height: 44px;
  font-family: 'VT323'; font-size: 16px; letter-spacing: 0.06em;
  padding: 10px 8px; background: #0e0a1a; color: #f2ecff;
  border: 2px solid; cursor: pointer;
