.char-btn:hover:not(.disabled) { transform: scale(1.02); }
.char-btn.evolve { background: #0a0612; }
.char-btn.disabled { opacity: 0.6; cursor: not-allowed; }

.camp-rank-bar {
  position: relative; width: 92px; height: 8px; margin-top: 4px;
  background: #0a0612; border: 1px solid #ffffff22; border-radius: 4px; overflow: hidden;
}
.camp-rank-fill {
  height: 100%; background: linear-gradient(90deg, var(--rune), #fff6c8);
  box-shadow: 0 0 8px var(--rune), 0 0 3px #fff inset;
  transition: width 0.3s ease;
}
.camp-rank-bar-label {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-family: 'VT323'; font-size: 8px; color: #fff; text-shadow: 0 1px 1px #000; letter-spacing: 0.05em;
}
.camp-attr-pulse { animation: attrPulse 1.4s ease-in-out infinite; }
.char-bonuses { background: #0a0612; border: 1px solid #ffffff11; padding: 10px; margin-top: 12px; border-radius: 2px; }
.char-attr-section { background: #0a0612; border: 1px solid #b362ff22; padding: 12px; margin-top: 12px; border-radius: 2px; }
/* (The attribute rolldown lives in .camp-attr-panel now — see the profile
   bar block above. It was an absolutely-positioned dropdown here, which the
   sidebar's overflow:hidden clipped.) */
.char-attr-header { display: flex; justify-content: space-between; align-items: center; font-family: 'VT323'; font-size: 16px; color: #c890ff; letter-spacing: 0.15em; margin-bottom: 4px; }
.char-attr-free { font-size: 11px; color: #4a3a6e; letter-spacing: 0.1em; }
.char-attr-free.has { color: #ffd700; animation: attrPulse 1.4s ease-in-out infinite; }
.char-attr-desc { font-size: 10px; color: #4a3a6e; margin-bottom: 10px; letter-spacing: 0.05em; }
.char-rar-table { border-top: 1px solid #ffffff11; margin-top: 12px; padding-top: 8px; }
.char-rar-row { display: flex; gap: 12px; align-items: center; padding: 5px 0; border-left: 3px solid; padding-left: 8px; margin-bottom: 3px; font-family: 'VT323'; font-size: 15px; }
.char-rar-row.cur { background: #ffffff08; }

/* ═══════════════════════════════════════════
   TALENT TREE
═══════════════════════════════════════════ */
.talent-grid {
  display: flex; flex-direction: column; align-items: center; gap: 0; padding: 16px 8px;
  position: relative;
}
.talent-node {
  position: relative;
  width: 220px; padding: 10px 16px;
  background: #0e0a1a;
  border: 2px solid #ffffff22;
  cursor: pointer;
  text-align: center;
  transition: all 0.2s;
  z-index: 1;
  border-radius: 4px;
}
.talent-node.available { border-color: #4dffd4; box-shadow: 0 0 12px #4dffd433; }
.talent-node.available:hover { transform: scale(1.04); box-shadow: 0 0 20px #4dffd466; }
.talent-node.bought { border-color: #b362ff44; background: #1a0e28; }
.talent-node.locked { opacity: 0.45; cursor: not-allowed; }
.talent-node.milestone {
  width: 250px; border-width: 3px;
  background: linear-gradient(135deg, #1a0e28 0%, #0e0a1a 100%);
}
.talent-node.milestone.available { border-color: #ff7a1a; box-shadow: 0 0 20px #ff7a1a44; }
.talent-node.milestone.bought { border-color: #ff7a1a88; }
.talent-icon { font-size: 22px; }
.talent-name { font-family: 'VT323'; font-size: 15px; color: var(--ink); letter-spacing: 0.1em; margin-bottom: 2px; }
.talent-stat { font-size: 11px; color: var(--accent-2); }
.talent-cost { font-size: 11px; color: #4dff91; margin-top: 2px; }
.talent-done { color: #ffd700; font-size: 13px; }
.talent-locked { color: #ffffff33; font-size: 14px; }
.talent-line {
  position: absolute; top: 0; left: 50%; transform: translateX(-50%);
  width: 2px; height: 20px; background: #ffffff22;
  z-index: 0; margin-top: -20px;
}
.talent-line.lit { background: #4dffd466; }

/* Tutorial bubble animation */
@keyframes tutBubble {
  from { opacity: 0; transform: translateX(-50%) translateY(10px); }
  to   { opacity: 1; transform: translateX(-50%) translateY(0); }
}

/* ═══════════════════════════════════════════
   COMBO METER
═══════════════════════════════════════════ */
.combo-display {
  position: absolute; bottom: 160px; left: 50%; transform: translateX(-50%);
  text-align: center; pointer-events: none; z-index: 4;
  transition: opacity 0.3s;
}
.combo-count { font-family: 'VT323'; color: #ffd166; text-shadow: 0 0 18px #ffd166aa; font-weight: 900; line-height: 1; }
.combo-label { font-family: 'VT323'; font-size: 12px; color: #ffd16688; letter-spacing: 0.3em; margin-top: -4px; }
.combo-bar { width: 80px; height: 3px; background: #ffffff22; border-radius: 2px; margin: 4px auto 0; overflow: hidden; }
.combo-fill { height: 100%; background: #ffd166; border-radius: 2px; transition: width 0.1s linear; }
.combo-multiplier {
  margin-top: 4px; font-family: 'VT323', monospace; font-size: 13px; letter-spacing: 0.2em;
  color: #ff9900; text-shadow: 0 0 10px #ff990099;
  animation: pulse 0.6s ease-in-out infinite;
}

/* ═══════════════════════════════════════════
   PINBALL SCORE
═══════════════════════════════════════════ */
.hud-score {
  position: absolute; top: 8px; right: 14px; z-index: 4;
  display: flex; flex-direction: column; align-items: flex-end;
  font-family: 'VT323', monospace; pointer-events: none;
}
.hud-score-label { font-size: 11px; letter-spacing: 0.35em; color: #4dffe088; }
.hud-score-value { font-size: 24px; color: #4dffe0; text-shadow: 0 0 14px #4dffe0aa; font-weight: 900; }

/* ═══════════════════════════════════════════
   CARD SHOP — SECTIONS + JACKPOT
═══════════════════════════════════════════ */
.section-chooser { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; max-width: 420px; margin: 0 auto; }
.section-btn {
  background: #0a1618; border: 2px solid #ffffff22;
  padding: 16px 10px; cursor: pointer; display: flex; flex-direction: column; align-items: center;
  font-family: 'VT323'; transition: all 0.2s;
}
.section-btn:hover { border-color: #4dffd4; box-shadow: 0 0 16px #4dffd433; transform: scale(1.03); }
.cs-jackpot-flash { animation: jackpotFlash 1s ease; }
@keyframes jackpotFlash {
  0%, 100% { box-shadow: none; }
  25% { box-shadow: 0 0 60px #ffd70099, inset 0 0 40px #ffd70033; }
  50% { box-shadow: 0 0 80px #ff7a1a99, inset 0 0 50px #ff7a1a33; }
  75% { box-shadow: 0 0 60px #ffd70099, inset 0 0 40px #ffd70033; }
}
.cs-jackpot-banner {
  background: linear-gradient(90deg, #1a0a00, #ffd70022, #1a0a00);
  border: 2px solid #ffd700;
  color: #ffd700; font-family: 'VT323'; font-size: 20px; letter-spacing: 0.3em;
  padding: 10px; margin: 8px 0; text-align: center;
  animation: jackpotPulse 0.6s infinite alternate;
}
@keyframes jackpotPulse { from { opacity: 0.8; } to { opacity: 1; box-shadow: 0 0 20px #ffd70066; } }
.cs-match-banner {
  background: #0a1420; border: 1px solid #4dc4ff66;
  color: #4dc4ff; font-family: 'VT323'; font-size: 16px; letter-spacing: 0.2em;
  padding: 6px; margin: 6px 0; text-align: center;
}
.cs-result.jackpot { border: 2px solid #ffd700; background: #1a1200; box-shadow: 0 0 24px #ffd70044; }
.cs-result.two-match { border: 1px solid #4dc4ff66; background: #001020; }
.slot-window {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px;
  background: #06040a; border: 2px solid #000; padding: 8px;
  margin: 0 auto 12px; max-width: 420px;
}
.slot-cell {
  background: linear-gradient(180deg, #141826 0%, #06080f 100%);
  border: 1px solid #ffffff15; min-height: 100px; height: 100px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  transition: box-shadow 0.4s;
}
.camp-tab-divider { width: 1px; height: 24px; background: #ffffff22; align-self: center; }

/* ═══════════════════════════════════════════
   POE2 SKILL TREE — Complete UI
═══════════════════════════════════════════ */
.poe-overlay {
  position: fixed; inset: 0; z-index: 200;
  background: rgba(2,0,8,0.92);
  display: flex; align-items: center; justify-content: center;
  backdrop-filter: blur(6px);
  touch-action: none;
  overscroll-behavior: none;
}
.poe-panel {
  width: 98vw; height: 96vh; max-width: 1600px;
  background: #06030f;
  border: 1px solid #2a1a4e;
  box-shadow: 0 0 60px rgba(100,50,200,0.3), inset 0 0 80px rgba(0,0,0,0.6);
  display: flex; flex-direction: column; overflow: hidden;
  position: relative;
}

/* Topbar */
.poe-topbar {
  display: flex; align-items: center; gap: 16px;
  padding: 10px 16px;
  background: linear-gradient(90deg, #0e0520 0%, #08031a 100%);
  border-bottom: 1px solid #2a1a4e;
  flex-shrink: 0;
}
.poe-topbar-left { display: flex; align-items: center; gap: 16px; flex: 1; }
.poe-topbar-right { display: flex; align-items: center; gap: 10px; }
.poe-title {
  font-family: 'VT323'; font-size: 22px; letter-spacing: 0.3em;
  color: #c890ff; text-shadow: 0 0 16px #b362ff88;
}
.poe-sp {
  font-family: 'VT323'; font-size: 18px; color: #4dffd4;
  background: #041020; padding: 4px 10px; border: 1px solid #4dffd422;
  display: inline-flex; align-items: center; gap: 6px;
}
.poe-hint { font-size: 10px; color: #3a2a5e; letter-spacing: 0.15em; display: none; }
@media (min-width: 900px) { .poe-hint { display: block; } }

@keyframes attrPulse {
  0%,100% { box-shadow: 0 0 6px #ffd70044; }
  50%      { box-shadow: 0 0 16px #ffd700aa; }
}
.poe-close-btn {
  background: none; border: 1px solid #3a2a6e; color: #6a4a9e;
  font-size: 16px; padding: 4px 10px; cursor: pointer;
  transition: all 0.2s;
  min-height: 44px; min-width: 44px;
  overflow: visible; clip-path: none;
}
.poe-close-btn:hover { border-color: #ff3146; color: #ff3146; }

/* Body */
.poe-body {
  flex: 1; display: flex; min-height: 0;
}

/* Canvas */
.poe-canvas {
  flex: 1; position: relative; overflow: hidden;
  background: radial-gradient(circle at 50% 50%, #100630 0%, #070218 55%, #020008 100%);
  cursor: grab;
  touch-action: none;
  overscroll-behavior: none;
}
.poe-canvas:active { cursor: grabbing; }

/* Zoom indicator */
.poe-zoom-hint {
  position: absolute; bottom: 10px; left: 12px;
  font-family: 'VT323'; font-size: 12px; color: #3a2a5e;
  letter-spacing: 0.1em; pointer-events: none;
}

/* "Fit whole tree" — the way back to the overview. Load-bearing on phone,
   where the tree now opens zoomed in to a usable touch target instead of
   fitting the whole 360° wheel into 390px of width. Sized to the 44px
   minimum touch target and pushed clear of the iOS home indicator. */
.poe-fit-btn {
  position: absolute; bottom: calc(10px + env(safe-area-inset-bottom)); right: 12px;
  display: flex; align-items: center; gap: 6px;
  min-height: 44px; padding: 0 14px;
  background: linear-gradient(#231a3e, #150e28);
  border: 1px solid #4a3a6e; border-radius: 8px;
  box-shadow: 0 2px 0 #000, inset 0 1px 0 rgba(255,255,255,0.07);
  color: #b9a8e8; font-family: 'VT323'; font-size: 15px; letter-spacing: 0.12em;
  cursor: pointer; touch-action: manipulation;
  overflow: visible; clip-path: none;
}
.poe-fit-btn:active { transform: translateY(1px); box-shadow: 0 1px 0 #000; }
@media (hover: hover) {
  .poe-fit-btn:hover { border-color: #7a5fd0; color: #e0d4ff; }
}

.poe-dash-btn {
  position: absolute; bottom: calc(10px + env(safe-area-inset-bottom)); right: 92px;
  display: flex; align-items: center; gap: 6px;
  min-height: 44px; padding: 0 14px;
  background: linear-gradient(#12332c, #0a1c18);
  border: 1px solid #2a7a68; border-radius: 8px;
  box-shadow: 0 2px 0 #000, inset 0 1px 0 rgba(255,255,255,0.07);
  color: #4dffd4; font-family: 'VT323'; font-size: 15px; letter-spacing: 0.12em;
  cursor: pointer; touch-action: manipulation;
  overflow: visible; clip-path: none;
}
.poe-dash-btn:active { transform: translateY(1px); box-shadow: 0 1px 0 #000; }
@media (hover: hover) {
  .poe-dash-btn:hover { border-color: #4dffd4; color: #c8fff4; }
}

.poe-dash-ring { animation: poeDashRing 1.6s ease-in-out infinite; }
@keyframes poeDashRing {
  0%, 100% { opacity: 0.35; }
  50%      { opacity: 1; }
}
.poe-dash-beam { animation: poeDashBeam 1.8s ease-in-out infinite; }
@keyframes poeDashBeam {
  0%, 100% { opacity: 0.16; }
  50%      { opacity: 0.38; }
}

.poe-dash-comic {
  position: absolute; left: 12px; bottom: calc(62px + env(safe-area-inset-bottom));
  width: min(292px, calc(100% - 24px));
  padding: 14px 16px 12px;
  background: #fff4d6;
  color: #1a1208;
  border: 3px solid #111;
  border-radius: 6px;
  box-shadow: 5px 5px 0 #111;
  z-index: 8;
  pointer-events: auto;
  overflow: visible; clip-path: none;
}
.poe-dash-comic-kicker {
  font-family: VT323, monospace; font-size: 12px; letter-spacing: 0.28em; color: #2a7a68;
}
.poe-dash-comic-title {
  font-family: 'Cinzel', Georgia, serif; font-size: 18px; letter-spacing: 0.08em;
  margin: 2px 0 8px;
}
.poe-dash-comic p {
  margin: 0 0 12px; font-family: VT323, monospace; font-size: 16px; line-height: 1.35;
}
.poe-dash-comic b { color: #0b5c4c; }
.poe-dash-comic button {
  width: 100%; min-height: 40px; border: 2px solid #111; cursor: pointer;
  font-family: VT323, monospace; font-size: 16px; letter-spacing: 0.16em;
  background: #4dffd4; color: #08241c;
  box-shadow: 2px 2px 0 #111;
  overflow: visible; clip-path: none;
}
.poe-dash-comic button:active { transform: translate(1px, 1px); box-shadow: 1px 1px 0 #111; }

/* Preview Panel */
.poe-preview {
  width: 0; overflow: hidden; transition: width 0.28s ease;
  /* Darker, warmer than the old flat purple UI panel — reads closer to a
     carved stone/parchment tablet, matching the bronze frame ring the
     tree itself now has. Content/copy is untouched, this is border +
     background only. */
  background: linear-gradient(180deg, #0c0810 0%, #060309 100%);
  border-left: 2px solid #6a4a20;
  box-shadow: inset 6px 0 18px -12px #000000, -3px 0 14px rgba(0,0,0,0.5);
  display: flex; flex-direction: column; padding: 0; flex-shrink: 0;
  /* Override the canvas/overlay's touch-action:none so this panel's own
     vertical scroll still works on touch (touch-action is intersected
     with ancestors, so without this the panel would be un-scrollable). */
  touch-action: pan-y;
}
.poe-preview.open {
  width: 316px; padding: 20px 16px; overflow-y: auto;
}

/* ── The inspect panel as a CARD, not a full-height sliver ──────────
   Timmy, 2026-08-17: "info köp gör den bättre inte en halv skärm sådär
   utan mer som ett kort ... få till ram på ... info korten".

   It used to be a flush column running the whole height of the screen
   with a single border-left, which read as a docked sidebar — a piece of
   chrome — rather than as the object you just picked up. Now it floats:
   inset from every edge, only as tall as its own content, vertically
   centred, with the same bronze frame language as the wheel. `height:
   fit-content` + `align-self: center` is what stops it stretching; the
   parent is a flex row, so without those it fills the cross axis. */
@media (min-width: 721px) {
  .poe-preview.open {
    align-self: center;
    height: fit-content;
    max-height: calc(100% - 40px);
    margin: 20px 20px 20px 0;
    border-radius: 14px;
    border: none;
    padding: 22px 18px;
    background:
      /* inner glow of the branch colour, so the card is keyed to the node */
      radial-gradient(120% 80% at 50% 0%,
        color-mix(in srgb, var(--bc, #b362ff) 14%, transparent) 0%, transparent 62%),
      linear-gradient(180deg, #17102a 0%, #0a0614 55%, #070310 100%);
    box-shadow:
      /* the bronze frame, built from rings rather than a border so the
         bevel can be two-tone like the wheel's own band */
      0 0 0 2px #0a0603,
      0 0 0 8px #6a4a20,
      0 0 0 9px #b58a44,
      0 0 0 12px #2a1c0c,
      0 18px 40px rgba(0,0,0,0.65),
      inset 0 1px 0 rgba(255,255,255,0.07);
  }
}
/* Mobile: a bottom sheet, not a side sliver. The previous fix floated the
   panel as a right-side overlay instead of squeezing the canvas, but at
   ~78vw wide × full height it still buried most of the tree behind it
   every time a node was inspected — "barely gives a good feeling". A
   sheet anchored to the bottom, capped at 62vh, leaves the whole tree
   visible above it and reads as the standard mobile inspect-panel
   pattern instead of a squeezed-down desktop sidebar. Animated via
   `transform` (not width/height) since the sheet's content height varies
   node to node and only a fixed-to-fixed value transitions smoothly. */
@media (max-width: 720px) {
  .poe-body { position: relative; }
  .poe-preview {
    position: absolute; left: 0; right: 0; bottom: 0; top: auto; z-index: 5;
    width: auto; max-width: none;
    max-height: 62vh; overflow-y: auto;
    padding: 18px 16px calc(18px + env(safe-area-inset-bottom, 0px));
    border-left: none; border-top: 2px solid #6a4a20;
    border-radius: 18px 18px 0 0;
    box-shadow: 0 -14px 34px rgba(0,0,0,0.65);
    transform: translateY(100%);
    transition: transform 0.3s cubic-bezier(0.2,0.9,0.3,1);
  }
  .poe-preview.open {
    width: auto; max-width: none;
    transform: translateY(0);
  }
}
/* Branch line: a bronze-ruled header with the branch's own colour as the
   rule, so the panel is colour-keyed to whatever you selected. */
.poe-prev-branch {
  font-family: 'VT323'; font-size: 13px; letter-spacing: 0.3em;
  margin-bottom: 12px; padding-bottom: 8px;
  border-bottom: 1px solid color-mix(in srgb, var(--bc, #b362ff) 30%, transparent);
}

/* The node, as the same glass orb the wheel draws. `.poe-prev-orb-icon` is
   overlaid rather than drawn inside the SVG because GameIcon renders its
   own top-level <svg>, and centring one inside another by hand is fiddlier
   than one absolutely-positioned flex box. */
/* Width/height come from the JSX (sized off the halo radius so the gradient
   is never clipped into a hard square by the viewBox). */
.poe-prev-orb {
  position: relative; margin: 2px auto 10px; flex-shrink: 0;
}
.poe-prev-orb-icon {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  pointer-events: none;
}
/* A slow bob, so the inspected node reads as live rather than as a
   screenshot of itself. Transform only.
   `--oscale` folds the responsive size into the same transform the bob
   uses — the two cannot be separate rules, because the later transform
   would simply replace the earlier one. The static declaration below
   keeps the scale correct when reduced-motion kills the animation. */
.poe-prev-orb { --oscale: 1; transform: scale(var(--oscale)); }
@media (prefers-reduced-motion: no-preference) {
  .poe-prev-orb { animation: poePrevOrb 4.2s ease-in-out infinite; }
  @keyframes poePrevOrb {
    0%, 100% { transform: translateY(0)    scale(var(--oscale)); }
    50%      { transform: translateY(-4px) scale(calc(var(--oscale) * 1.03)); }
  }
}
/* On the phone the sheet is capped at 62vh, and at full size the orb
   pushed BUY to the very bottom edge with BACK below the fold — the one
   control that must never need scrolling. Shrinking the orb and pulling
   the surrounding margin in reclaims about 60px, which is exactly the
   BACK button. */
@media (max-width: 720px) {
  .poe-prev-orb { --oscale: 0.66; margin: -22px auto -26px; }
}

/* The gain, on its own line, in green — the "colored stats" ask. Reads the
   node's real stat/val, so it is correct even when the description prose
   never spells the number out. */
.poe-prev-stat {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
  margin: 0 0 12px;
  padding: 8px 10px;
  background: linear-gradient(180deg, rgba(20,32,20,0.55), rgba(6,12,8,0.55));
  border: 1px solid rgba(92,255,157,0.22);
  border-left: 3px solid #5cff9d;
  border-radius: 3px;
}
.poe-prev-stat-label {
  font-family: 'VT323'; font-size: 13px; letter-spacing: 0.16em; color: #8fb8a0;
}
.poe-prev-stat-val {
  font-family: 'VT323'; font-size: 19px; color: #5cff9d;
  text-shadow: 0 0 10px rgba(92,255,157,0.45);
  white-space: nowrap;
}
/* Cinzel, not VT323 — matches the level-up cards' name treatment
   (.card-name) so the node name reads as a premium title rather than one
   more line in the same pixel-readout font every label on this screen
   already uses. */
.poe-prev-name {
  font-family: 'Cinzel', serif; font-weight: 800; font-size: 21px; color: #e0d0ff;
  letter-spacing: 0.04em; text-align: center; margin-bottom: 4px;
  text-shadow: 0 0 14px rgba(179,98,255,0.35);
}
.poe-prev-type {
  font-family: 'VT323'; font-size: 11px; letter-spacing: 0.3em;
  text-align: center; margin-bottom: 14px;
}
.poe-prev-desc {
  font-size: 12px; color: #9a8ab6; line-height: 1.6;
  border-left: 2px solid #2a1a4e; padding-left: 10px;
  margin-bottom: 14px;
}
.poe-prev-move {
  font-family: VT323, monospace; font-size: 15px; letter-spacing: 0.06em;
  color: #4dffd4; line-height: 1.35;
  border: 1px solid #1a4a42; background: #041814;
  padding: 8px 10px; margin: -6px 0 14px;
}
/* Levels as a segmented bar rather than loose pips. Pips stopped scaling
   once nodes could hold three levels — the row wrapped on a phone and the
   count stopped being readable at a glance. Segments always fill the
   available width, so 1/3 and 3/3 are the same shape. */
.poe-prev-level {
  display: flex; align-items: center; gap: 10px; margin-bottom: 10px;
}
.poe-lvl-bar {
  display: flex; gap: 3px; flex: 1; height: 14px;
  padding: 2px; background: #0a0616;
  border: 1px solid #4a3570; border-radius: 3px;
  box-shadow: inset 0 2px 4px rgba(0,0,0,0.7);
}
/* Empty segments carry a faint tint of the branch colour rather than being
   near-black: at 0/3 the whole bar was invisible against the panel, so it
   read as "no bar" instead of "no levels yet". */
.poe-lvl-seg {
  flex: 1; border-radius: 1px;
  background: color-mix(in srgb, var(--pc, #b362ff) 13%, #140a22);
  transition: background 0.25s, box-shadow 0.25s;
}
.poe-lvl-seg.on {
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--pc, #b362ff) 60%, #fff),
    var(--pc, #b362ff));
  box-shadow: 0 0 7px var(--pc, #b362ff);
}
.poe-lvl-text {
  font-family: 'VT323'; font-size: 14px; color: #8a7aae; white-space: nowrap;
}
/* Cost as a struck chip, not a loose line — it is a price, and prices read
   better boxed. */
.poe-prev-cost {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: 'VT323'; font-size: 14px; color: #4dffd4;
  margin-bottom: 14px; padding: 5px 10px;
  background: linear-gradient(180deg, #0d1c22, #061014);
  border: 1px solid #1d4a4a; border-radius: 3px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.05);
}
.poe-prev-cost strong { color: #b8fff0; font-weight: 400; font-size: 17px; }
.poe-prev-locked {
  background: #1a0a2e; border: 1px solid #3a1a5e;
  color: #8a5aae; font-size: 11px; padding: 8px 10px;
  border-radius: 2px; margin-bottom: 12px;
}
.poe-prev-locked em { color: #b362ff; font-style: normal; }
.poe-prev-maxed {
  font-family: 'VT323'; font-size: 18px; color: #ffd700;
  letter-spacing: 0.3em; text-align: center; margin-bottom: 12px;
  text-shadow: 0 0 12px #ffd70088;
}
/* BUY — the most important control on the screen, so it is the only thing
   in the panel that moves on its own. Colour-keyed to the selected branch
   (--bc) so it belongs to the node you are buying rather than being a
   generic purple button, with a sheen that sweeps across it while it is
   affordable. 46px tall to clear the 44px touch-target minimum. */
.poe-buy-btn {
  position: relative; overflow: visible; clip-path: none;
  width: 100%; min-height: 46px; padding: 10px 12px;
  font-family: 'VT323'; font-size: 18px; letter-spacing: 0.16em;
  cursor: pointer; margin-bottom: 8px; border: none; border-radius: 4px;
  transition: transform 0.12s, box-shadow 0.2s, background 0.2s;
  touch-action: manipulation;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
}
.poe-buy-btn.can {
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--bc, #b362ff) 26%, #120a26) 0%,
      color-mix(in srgb, var(--bc, #b362ff) 10%, #08040f) 100%);
  border: 1px solid var(--bc, #b362ff);
  color: #fff;
  text-shadow: 0 0 10px var(--bc, #b362ff);
  box-shadow: 0 0 14px color-mix(in srgb, var(--bc, #b362ff) 28%, transparent),
              inset 0 1px 0 rgba(255,255,255,0.14),
              0 3px 0 rgba(0,0,0,0.6);
}
/* The sheen. A skewed highlight sweeping left to right on a long, mostly
   idle cycle — present enough to pull the eye, slow enough not to nag. */
.poe-buy-btn.can::after {
  content: ''; position: absolute; top: -60%; bottom: -60%; width: 40px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.30), transparent);
  transform: skewX(-18deg);
  animation: poeBuySheen 3.4s ease-in-out infinite;
}
@keyframes poeBuySheen {
  0%, 62%  { left: -60px; }
  92%, 100% { left: 108%; }
}
@media (hover: hover) {
  .poe-buy-btn.can:hover {
    background:
      linear-gradient(180deg,
        color-mix(in srgb, var(--bc, #b362ff) 42%, #150c2c) 0%,
        color-mix(in srgb, var(--bc, #b362ff) 18%, #0b0614) 100%);
    box-shadow: 0 0 26px color-mix(in srgb, var(--bc, #b362ff) 55%, transparent),
                inset 0 1px 0 rgba(255,255,255,0.2),
                0 3px 0 rgba(0,0,0,0.6);
  }
}
/* Press: the button physically goes down onto its own shadow. */
.poe-buy-btn.can:active {
  transform: translateY(3px);
  box-shadow: 0 0 18px color-mix(in srgb, var(--bc, #b362ff) 45%, transparent),
              inset 0 2px 5px rgba(0,0,0,0.55);
}
.poe-buy-btn.cant {
  background: #0b0618; border: 1px solid #241738; color: #4a3a6e;
  cursor: not-allowed; box-shadow: inset 0 2px 5px rgba(0,0,0,0.5);
}
@media (prefers-reduced-motion: reduce) {
  .poe-buy-btn.can::after { animation: none; display: none; }
}

.poe-desel-btn {
  width: 100%; min-height: 40px; background: none;
  border: 1px solid #2a1a4e; border-radius: 4px;
  color: #6a5a8e; font-family: 'VT323'; font-size: 14px;
  padding: 6px; cursor: pointer; letter-spacing: 0.12em;
  transition: color 0.18s, border-color 0.18s;
  touch-action: manipulation;
  overflow: visible; clip-path: none;
}
@media (hover: hover) {
  .poe-desel-btn:hover { color: #b0a0d8; border-color: #4a3a7e; }
}
.poe-desel-btn:active { transform: translateY(1px); }
.poe-prev-empty {
  display: flex; flex-direction: column; align-items: center;
  padding: 20px 0; min-height: 100%;
}
.poe-branch-summary {
  width: 100%; display: flex; justify-content: space-between; align-items: center;
  padding: 3px 0; border-bottom: 1px solid #120820;
  font-family: 'VT323'; font-size: 12px;
  color: var(--bc, #6a5a8e);
}

/* Attribute rows — reused by the Profile/Character panel's Attributes section */
.poe-attr-grid { display: flex; flex-direction: column; gap: 6px; }
.poe-attr-row {
  display: flex; align-items: center; gap: 10px;
  background: #0a0420; border: 1px solid #1a0a30; padding: 8px 10px;
  transition: border-color 0.2s;
}
.poe-attr-row:hover { border-color: #3a2a5e; }
.poe-attr-icon { font-size: 18px; width: 24px; text-align: center; }
.poe-attr-info { flex: 1; display: flex; flex-direction: column; }
.poe-attr-name { font-family: 'VT323'; font-size: 14px; color: #c0b0e0; letter-spacing: 0.1em; }
.poe-attr-desc2 { font-size: 10px; color: #5a4a7e; }
.poe-attr-ctl { display: flex; align-items: center; gap: 8px; }
.poe-attr-val { font-family: 'VT323'; font-size: 18px; color: #4dffd4; min-width: 24px; text-align: center; }
.poe-attr-add {
  width: 28px; height: 28px; background: #1a0840; border: 1px solid #b362ff;
  color: #b362ff; font-size: 18px; cursor: pointer; line-height: 1;
  transition: all 0.2s;
}
.poe-attr-add:hover:not(.disabled) { background: #3a10a0; box-shadow: 0 0 12px #b362ff66; }
.poe-attr-add.disabled { border-color: #2a1a4e; color: #3a2a5e; cursor: not-allowed; }

/* Toast */
.poe-toast {
  position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%);
  background: #0e0820; border: 1px solid #b362ff;
  color: #e0c0ff; font-family: 'VT323'; font-size: 16px; letter-spacing: 0.2em;
  padding: 8px 20px; pointer-events: none; z-index: 50;
  animation: toastIn 0.2s ease;
}
@keyframes toastIn { from { opacity:0; transform: translateX(-50%) translateY(10px); } to { opacity:1; transform: translateX(-50%) translateY(0); } }

/* Meta locked state */
.upgrade-card.meta-locked {
  opacity: 0.55;
  border-color: #2a1a4e !important;
  background: #0a0618 !important;
  filter: grayscale(0.3);
}
.upgrade-card.meta-locked .name { color: #5a4a7e !important; }
.meta-lock-msg {
  font-size: 10px; color: #6a5090; letter-spacing: 0.05em;
  margin-top: 4px; display: flex; align-items: center; gap: 4px; flex-wrap: wrap;
}
.meta-lock-msg em { color: #9a70c0; }

/* ═══════════════════════════════════════════
   SKILL TREE — Start node pulse animation
═══════════════════════════════════════════ */
.poe-start-pulse {
  animation: startPulse 1.8s ease-in-out infinite;
}
@keyframes startPulse {
  0%,100% { opacity: 0.3; r: 26px; }
  50%      { opacity: 0.7; r: 32px; }
}

/* ═══════════════════════════════════════════
   GEAR PANEL
═══════════════════════════════════════════ */
.gear-panel { display: flex; flex-direction: column; height: 100%; }
.gear-tabs { display: flex; gap: 4px; padding: 0 0 12px 0; }
.gear-tab {
  font-family: 'VT323'; font-size: 13px; padding: 6px 14px;
  background: #0a0420; border: 1px solid #2a1a4e; color: #5a4a7e;
  cursor: pointer; letter-spacing: 0.15em; transition: all 0.2s;
}
.gear-tab.active, .gear-tab:hover { border-color: #b362ff; color: #b362ff; background: #1a0840; }
.gear-toast {
  position: fixed; bottom: 40px; left: 50%; transform: translateX(-50%);
  background: #0e0820; border: 1px solid #b362ff; color: #e0c0ff;
  font-family: 'VT323'; font-size: 15px; padding: 8px 20px; z-index: 99;
  animation: toastIn 0.2s ease;
}
.gear-empty {
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; padding: 60px 0; color: #4a3a6e;
  font-size: 13px; letter-spacing: 0.1em;
}

/* Paperdoll */
.gear-paperdoll { display: flex; gap: 20px; flex-wrap: wrap; }
.gear-doll-bg {
  position: relative; width: 280px; height: 380px;
  background: radial-gradient(ellipse at 50% 40%, #12083a 0%, #060110 100%);
  border: 1px solid #1a0a3e; flex-shrink: 0;
}
/* Procedural character silhouette — matches the in-game player's teal
   water-drop body instead of a single bare floating emoji ("ugly, doesn't
   fit the character" per feedback). Plain CSS shapes, no art asset needed,
   consistent with the rest of the game's fully-procedural visual identity. */
/* The paperdoll figure is the same silhouette as the in-game hero (see
   game/heroShape.js) rendered as SVG. It used to be a stack of divs shaped
   like a humanoid, which is why it read as a different character. */
.gear-doll-char {
  position: absolute; top: 34px; left: 50%; transform: translateX(-50%);
  width: 190px; height: 210px;
  pointer-events: none;
  filter: drop-shadow(0 0 18px rgba(95,214,255,0.32));
  animation: dollBreathe 3.6s ease-in-out infinite;
}
/* Idle breathing, matching the in-game character's squash/stretch. */
@keyframes dollBreathe {
  0%, 100% { transform: translateX(-50%) scale(1, 1); }
  50%      { transform: translateX(-50%) scale(1.025, 0.982); }
}
.doll-glow {
  position: absolute; top: 46px; left: 50%; transform: translateX(-50%);
  width: 130px; height: 130px; border-radius: 50%;
  background: radial-gradient(circle, rgba(95,214,255,0.28) 0%, transparent 70%);
  filter: blur(6px);
  pointer-events: none;
}
.gear-art-row {
  position: absolute;
  left: 10px; right: 10px; bottom: 10px;
  display: flex; gap: 8px; justify-content: center;
  z-index: 2;
}
.gear-doll-art {
  width: 72px; min-height: 58px; padding: 6px 4px 4px;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  cursor: pointer;
}
/* Quick equip popover — appears next to the paperdoll/artifact slots */
.gear-popover {
  position: relative; width: 260px; max-height: 320px;
  background: #0a0420ee; border: 2px solid #2a1a4e;
  box-shadow: 0 0 20px #000a, 0 0 0 1px #4dffd422;
  padding: 10px; display: flex; flex-direction: column; gap: 6px;
  z-index: 5;
}
.gear-popover-head {
  display: flex; align-items: center; justify-content: space-between;
  font-family: 'VT323', monospace; font-size: 13px; letter-spacing: 0.15em; color: #4dffd4;
  border-bottom: 1px solid #2a1a4e; padding-bottom: 6px;
}
.gear-popover-close {
  background: none; border: none; color: #8a7aae; cursor: pointer; font-size: 14px; padding: 0 4px;
}
.gear-popover-close:hover { color: #ff5566; }
.gear-popover-list { overflow-y: auto; max-height: 240px; display: flex; flex-direction: column; gap: 4px; }
.gear-popover-empty { font-family: 'VT323'; font-size: 12px; color: #4a3a6e; padding: 10px 0; text-align: center; }
.gear-popover-row {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px;
  background: #12062a; border-left: 3px solid var(--rc, #2a1a4e);
  padding: 6px 8px; cursor: pointer; position: relative;
  transition: background 0.15s;
}
.gear-popover-row:hover { background: #1a0a3a; }
.gear-popover-row.eq { background: #0f2a1a; }
.gear-popover-row.disabled { opacity: 0.4; cursor: not-allowed; }
.gear-popover-name { font-family: 'VT323'; font-size: 12px; color: var(--rc); flex: 1 1 100%; }
.gear-popover-stat { font-family: 'VT323'; font-size: 10px; color: #9a8fbe; }
.gear-popover-armor { font-family: 'VT323'; font-size: 10px; color: #ffd166; }
.gear-popover-badge {
  position: absolute; top: 4px; right: 6px;
  font-family: 'VT323'; font-size: 9px; background: #4dff91; color: #05130c;
  padding: 1px 5px; letter-spacing: 0.1em;
}
.gear-slot {
  position: absolute; width: 48px; height: 48px;
  background: #0a0420; border: 2px solid var(--rc, #2a1a4e);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  cursor: pointer; transition: all 0.2s; font-size: 11px;
}
.gear-slot.filled { background: #12062a; }
.gear-slot:hover { transform: scale(1.08); box-shadow: 0 0 12px var(--rc, #2a1a4e); }
.gear-slot-label {
  font-family: 'VT323'; font-size: 8px; color: #5a4a6e; margin-top: 2px; letter-spacing: 0.1em;
}
.gear-slot-icon { font-size: 22px; }
.gear-slot-stat { font-family: 'VT323'; font-size: 9px; color: var(--rc); }
/* Slot positions */
.gear-slot-helmet  { top:  12px; left:  50%; transform: translateX(-50%); }
.gear-slot-chest   { top:  80px; left:  50%; transform: translateX(-50%); }
.gear-slot-arms    { top:  80px; left:  10px; }
.gear-slot-ring    { top: 160px; left:  10px; }
.gear-slot-legs    { top: 160px; left:  50%; transform: translateX(-50%); }
.gear-slot-amulet  { top:  80px; right: 10px; }
.gear-slot-boots   { top: 250px; left:  50%; transform: translateX(-50%); }

/* Artifact Gacha Machine */
.gacha-machine {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  background: linear-gradient(90deg, #1a1006 0%, #12062a 100%);
  border: 2px solid #ff7a1a44; padding: 12px 16px; margin-bottom: 16px;
}
.gacha-machine-icon { font-size: 32px; }
.gacha-machine-info { flex: 1; min-width: 160px; }
.gacha-machine-title { font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.12em; color: #ffd166; }
.gacha-machine-sub { font-family: 'VT323', monospace; font-size: 11px; color: #8a7aae; }
.gacha-machine-tokens { font-family: 'VT323', monospace; font-size: 16px; color: #4dffe0; }

@keyframes gachaRevealIn {
  0%   { opacity: 0; transform: scale(0.6) rotate(-8deg); }
  60%  { opacity: 1; transform: scale(1.08) rotate(2deg); }
  100% { opacity: 1; transform: scale(1) rotate(0deg); }
}
.gacha-reveal {
  background: radial-gradient(circle at 50% 20%, color-mix(in srgb, var(--rc) 25%, #0a0612) 0%, #0a0612 75%);
  border: 3px solid var(--rc); box-shadow: 0 0 40px var(--rc);
  padding: 28px 32px; text-align: center; max-width: 320px;
  animation: gachaRevealIn 450ms cubic-bezier(.2,.9,.3,1.4) both;
}
.gacha-reveal-icon { font-size: 56px; filter: drop-shadow(0 0 16px var(--rc)); }
.gacha-reveal-rarity { font-family: 'VT323', monospace; font-size: 16px; letter-spacing: 0.3em; color: var(--rc); margin-top: 6px; }
.gacha-reveal-name { font-family: 'Cinzel', serif; font-weight: 800; font-size: 20px; color: #fff; margin: 6px 0 10px; }

/* Artifact slots — generic (not body-part typed), shown as a row of cards */
.artifact-slots-row { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; }
.artifact-slot {
  width: 110px; min-height: 84px;
  background: #0a0420; border: 2px solid var(--rc, #2a1a4e);
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px;
  cursor: pointer; transition: all 0.2s; padding: 8px;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.artifact-slot.filled { background: #1a1006; box-shadow: 0 0 10px var(--rc); }
.artifact-slot:hover { transform: scale(1.05); box-shadow: 0 0 14px var(--rc, #2a1a4e); }
.artifact-slot-icon, .artifact-slot-empty-icon { font-size: 24px; }
.artifact-slot-empty-icon { opacity: 0.22; }
.artifact-slot-name { font-family: 'VT323', monospace; font-size: 10px; color: var(--rc); text-align: center; line-height: 1.15; }
.artifact-slot-label { font-family: 'VT323', monospace; font-size: 8px; color: #5a4a6e; letter-spacing: 0.1em; }

.gear-stats-summary { flex: 1; min-width: 200px; }
.gear-stats-title { font-family:'VT323'; font-size:14px; color:#4a3a6e; letter-spacing:.2em; margin-bottom:10px; }
.gear-stat-row { display:flex; gap:8px; align-items:center; font-family:'VT323'; font-size:12px; padding:4px 0; border-bottom:1px solid #120820; }

/* Inventory */
.gear-inv-grid { display:flex; flex-wrap:wrap; gap:6px; padding-bottom:10px; }
.gear-item {
  width:120px; padding:8px; background:#0a0420; border:1px solid var(--rc,#2a1a4e);
  cursor:pointer; transition:all 0.2s; position:relative;
}
.gear-item.sel { border-color: #ffd700; }
.gear-item.equipped::after { content:'EQ'; position:absolute; top:2px; right:4px; font-family:'VT323'; font-size:9px; color:#ffd700; }
.gear-item:hover { background: #120835; box-shadow: 0 0 8px var(--rc,#2a1a4e); }
.gear-item-icon { font-size:20px; margin-bottom:4px; }
.gear-item-info { display:flex; flex-direction:column; gap:2px; }
.gear-item-name { font-family:'VT323'; font-size:12px; line-height:1.2; }
.gear-item-stat { font-size:10px; color:#8a7a9e; }
.gear-equipped-badge { display:none; }
.gear-detail {
  background: #0e0525; border: 1px solid var(--rc,#2a1a4e);
  padding: 14px; margin-top: 10px;
}
.gear-detail-name { font-family:'VT323'; font-size:18px; color:#e0d0ff; margin-bottom:4px; }
.gear-detail-rarity { font-family:'VT323'; font-size:12px; letter-spacing:.2em; margin-bottom:8px; }
.gear-detail-stat { font-size:13px; color:#9a8ab6; margin-bottom:12px; }
.gear-detail-btns { display:flex; gap:8px; }
.gear-btn {
  font-family:'VT323'; font-size:13px; padding:6px 14px;
  border:none; cursor:pointer; letter-spacing:.1em; transition:all .2s;
}
.gear-btn.equip { background:#1a0840; border:1px solid #b362ff; color:#e0c0ff; }
.gear-btn.equip:hover { background:#3a1080; }
.gear-btn.unequip { background:#0e0820; border:1px solid #3a2a5e; color:#5a4a7e; }
.gear-btn.drop { background:#0e0820; border:1px solid #ff3146; color:#ff3146; }
.gear-btn.forge { background:#1a0820; border:1px solid #ffd700; color:#ffd700; }

/* Forge */
.gear-forge { padding: 10px 0; }
.gear-forge-title { font-family:'VT323'; font-size:13px; color:#4a3a6e; letter-spacing:.15em; margin-bottom:14px; }
.gear-merge-list { display:flex; flex-direction:column; gap:8px; }
.gear-merge-row {
  display:flex; align-items:center; justify-content:space-between;
  background:#0a0420; border:1px solid #1a0a30; padding:10px 14px;
}
.gear-merge-info { display:flex; align-items:center; gap:10px; font-family:'VT323'; font-size:14px; }

/* ═══════════════════════════════════════════
   BATTLE PASS
═══════════════════════════════════════════ */
.bp-panel { display:flex; flex-direction:column; height:100%; }
.bp-header { display:flex; align-items:center; gap:14px; margin-bottom:8px; flex-wrap:wrap; }
.bp-title { font-family:'VT323'; font-size:20px; color:#c890ff; letter-spacing:.3em; }
.bp-progress { font-family:'VT323'; font-size:13px; color:#4dffd4; }
.bp-unclaimed {
  background:#1a0830; border:1px solid #ffd700; color:#ffd700;
  font-family:'VT323'; font-size:12px; padding:3px 10px;
  animation: attrPulse 1.4s ease-in-out infinite;
}
.bp-desc { font-size:10px; color:#4a3a6e; margin-bottom:14px; letter-spacing:.1em; }
.bp-track-wrap { margin-bottom: 10px; }
.bp-track-label {
  font-family: 'VT323', monospace; font-size: 12px; letter-spacing: 0.2em;
  margin-bottom: 4px; color: #ffd166;
}
.bp-premium .bp-track-label { color: #ffd700; text-shadow: 0 0 8px #ffd70066; }
.bp-premium .bp-node { border-color: #ffd70044; }
.bp-free .bp-track-label { color: #8a8a9a; }
.bp-track {
  display:flex; gap:6px; overflow-x:auto; padding:10px 0 16px;
  flex-wrap:nowrap; scrollbar-width:thin; scrollbar-color:#2a1a4e #050010;
}
.bp-node {
  min-width:80px; height:100px; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:4px;
  background:#0a0420; border:1px solid #1a0a30;
  position:relative; flex-shrink:0; cursor:default; transition:all .2s;
}
.bp-node.reached { border-color:#2a1a4e; background:#0e0628; }
.bp-node.claimable {
  border-color:#ffd700; cursor:pointer;
  box-shadow: 0 0 14px #ffd70033;
  animation: claimPulse 1.6s ease-in-out infinite;
}
@keyframes claimPulse {
  0%,100% { box-shadow: 0 0 8px #ffd70033; }
  50%      { box-shadow: 0 0 24px #ffd70088; }
}
.bp-node.claimed { background:#080318; }
.bp-node-icon { font-size:26px; }
.bp-node-label { font-family:'VT323'; font-size:10px; color:#6a5a8e; text-align:center; letter-spacing:.05em; }
.bp-check { position:absolute; top:4px; right:6px; color:#4dffd4; font-size:14px; }
.bp-glow-ring {
  position:absolute; inset:-4px; border:1px solid #ffd70066;
  animation: ringPulse 1.4s ease-in-out infinite;
}
@keyframes ringPulse { 0%,100% { opacity:.3; } 50% { opacity:.8; } }
.bp-node-num {
  position:absolute; bottom:4px; left:50%; transform:translateX(-50%);
  font-family:'VT323'; font-size:9px; color:#3a2a5e;
}
.bp-footer { padding:8px 0; }

/* ═══════════════════════════════════════════
   CODEX PANEL
═══════════════════════════════════════════ */
.codex-panel { display:flex; flex-direction:column; height:100%; }
.codex-header { display:flex; align-items:center; gap:14px; margin-bottom:8px; }
.codex-title { font-family:'VT323'; font-size:20px; color:#c890ff; letter-spacing:.3em; }
.codex-count { font-family:'VT323'; font-size:13px; color:#4a3a6e; }
.codex-tabs { display:flex; gap:4px; margin-bottom:12px; }
.codex-tab {
  font-family:'VT323'; font-size:12px; padding:5px 14px;
  background:#0a0420; border:1px solid #2a1a4e; color:#5a4a7e;
  cursor:pointer; letter-spacing:.1em; transition:all .2s;
}
.codex-tab.active, .codex-tab:hover { border-color:#b362ff; color:#b362ff; }
.codex-grid { display:flex; flex-direction:column; gap:6px; overflow-y:auto; flex:1; }
.codex-entry {
  display:flex; gap:12px; align-items:flex-start; position:relative;
  background:#0a0420; border:1px solid #1a0a30; padding:10px 12px;
  transition:border-color .2s;
}
/* Claim feedback — proof of concept for "every claim should be felt".
   Rises from the claim button, glowing the same green CountUp uses on the
   currency chips, so the two reads as one motion: a gem earned here,
   landing there. */
.codex-claim-burst {
  position:absolute; right:10px; top:6px;
  display:inline-flex; align-items:center; gap:3px;
  font-family:'VT323'; font-size:13px; color:#6dff9e;
  text-shadow:0 0 8px rgba(109,255,158,0.8);
  pointer-events:none; z-index:5;
  animation: codexClaimBurst 750ms ease-out forwards;
}
@keyframes codexClaimBurst {
  0%   { opacity:0; transform:translateY(4px) scale(0.85); }
  20%  { opacity:1; transform:translateY(0) scale(1.15); }
  70%  { opacity:1; transform:translateY(-14px) scale(1); }
  100% { opacity:0; transform:translateY(-24px) scale(0.9); }
}
.codex-entry.found { border-color:#1a0a40; }
.codex-entry.boss { border-color:#2a0a20; }
.codex-entry-icon { font-size:14px; margin-top:2px; flex-shrink:0; }
.codex-entry-info { display:flex; flex-direction:column; gap:3px; }
.codex-entry-name { font-family:'VT323'; font-size:14px; color:#c0b0e0; letter-spacing:.1em; }
.codex-entry-lore { font-size:11px; color:#5a4a7e; line-height:1.5; }
.codex-entry-kills { font-family:'VT323'; font-size:11px; color:#4dffd4; margin-top:2px; }

/* ═══════════════════════════════════════════
   CLAIM BADGE — a living waterdrop, "something to claim here"
═══════════════════════════════════════════ */
.claim-badge {
  display: inline-flex; align-items: center; justify-content: center;
  position: absolute; top: 1px; right: 3px;
  pointer-events: none;
  animation: dropBreathe 2.2s ease-in-out infinite;
  z-index: 10;
  line-height: 1;
}
.claim-badge-ring {
  transform-origin: 10px 15px;
  animation: dropRipple 2.2s ease-out infinite;
}
@keyframes dropBreathe {
  0%, 100% { transform: translateY(0) scale(1); filter: drop-shadow(0 0 2px #4dc4ff77); }
  50%      { transform: translateY(-1.5px) scale(1.08); filter: drop-shadow(0 0 7px #8fe6ffdd); }
}
@keyframes dropRipple {
  0%   { opacity: 0.55; transform: scale(0.7); }
  70%  { opacity: 0; transform: scale(1.5); }
  100% { opacity: 0; transform: scale(1.5); }
}

/* ═══════════════════════════════════════════
   PATROL PANEL
═══════════════════════════════════════════ */
.patrol-panel { display:flex; flex-direction:column; gap:10px; height:100%; overflow-y:auto; }
.patrol-header { display:flex; align-items:center; gap:14px; padding-bottom:6px; border-bottom:1px solid #1a0a30; }
.patrol-title  { font-family:'VT323'; font-size:20px; color:#c890ff; letter-spacing:.3em; }
.patrol-slots  { font-family:'VT323'; font-size:13px; color:#4a3a6e; }
.patrol-pet-bonus { font-family:'VT323'; font-size:12px; color:#51cf66; background:#0a2010; border:1px solid #51cf6633; padding:3px 8px; }

/* Active mission card */
.patrol-mission {
  display:flex; align-items:center; gap:12px; padding:12px 14px;
  background:#0a0420; border:1px solid #1a0a30; transition:border-color .2s;
}
.patrol-mission.done { border-color:#ffd700; background:#12080a; animation: claimPulse 1.6s ease-in-out infinite; }
.patrol-m-icon { font-size:28px; flex-shrink:0; }
.patrol-m-info { flex:1; display:flex; flex-direction:column; gap:4px; }
.patrol-m-name { font-family:'VT323'; font-size:16px; color:#c0b0e0; letter-spacing:.1em; }
.patrol-m-status { font-family:'VT323'; font-size:12px; color:#6a5a8e; }
.patrol-mission.done .patrol-m-status { color:#ffd700; }
.patrol-bar { height:4px; background:#1a0a30; border-radius:2px; overflow:hidden; }
.patrol-bar-fill { height:100%; background:#b362ff; transition:width 2s linear; }

.patrol-btn { font-family:'VT323'; font-size:13px; padding:7px 14px; border:none; cursor:pointer; letter-spacing:.1em; transition:all .2s; white-space:nowrap; }
.patrol-btn.claim  { background:#1a0830; border:1px solid #ffd700; color:#ffd700; }
.patrol-btn.claim:hover { background:#2a1040; box-shadow:0 0 12px #ffd70044; }
.patrol-btn.cancel { background:none; border:1px solid #2a1a4e; color:#4a3a6e; font-size:14px; }
.patrol-btn.send   { background:#12083a; border:1px solid #b362ff; color:#c890ff; }
.patrol-btn.send:hover:not(:disabled) { background:#1a0850; }
.patrol-btn:disabled { opacity:.35; cursor:not-allowed; }

.patrol-send-section { padding-top:8px; }
.patrol-send-title { font-family:'VT323'; font-size:13px; color:#4a3a6e; letter-spacing:.2em; margin-bottom:8px; }
.patrol-defs { display:flex; flex-direction:column; gap:6px; }
.patrol-def {
  display:flex; align-items:center; gap:12px; padding:10px 14px;
  background:#08031a; border:1px solid #150825;
}
.patrol-def-icon  { font-size:24px; flex-shrink:0; }
.patrol-def-info  { flex:1; display:flex; flex-direction:column; gap:2px; }
.patrol-def-name  { font-family:'VT323'; font-size:15px; color:#c0b0e0; letter-spacing:.1em; }
.patrol-def-desc  { font-size:10px; color:#4a3a6e; }
.patrol-def-rwd   { font-family:'VT323'; font-size:11px; color:#4dffd4; }
.patrol-full { font-family:'VT323'; font-size:13px; color:#4a3a6e; text-align:center; padding:20px; letter-spacing:.15em; }

/* ═══════════════════════════════════════════
   CODEX — Achievements + Claim buttons
═══════════════════════════════════════════ */
.codex-claim-hint {
  font-family:'VT323'; font-size:12px; background:#1a0830;
  border:1px solid #ffd70055; color:#ffd700; padding:3px 10px;
}
.codex-claim-btn {
  font-family:'VT323'; font-size:12px; padding:5px 10px; flex-shrink:0;
  background:#0e0525; border:1px solid #4dffd4; color:#4dffd4;
  cursor:pointer; letter-spacing:.05em; transition:all .2s; align-self:center;
}
.codex-claim-btn:hover { background:#0a2030; box-shadow:0 0 8px #4dffd422; }
.codex-claim-btn.boss-claim { border-color:#ff3146; color:#ff3146; }
.codex-claimed-badge {
  font-family:'VT323'; font-size:14px; color:#4dffd4; flex-shrink:0; align-self:center;
}
.codex-entry.claimed-ach { opacity:.5; }
.codex-ach-summary {
  font-family:'VT323'; font-size:12px; color:#4a3a6e; letter-spacing:.15em;
  padding:8px 0; margin-bottom:6px; border-bottom:1px solid #120820;
}
.ach-entry { cursor:default; }
.codex-ach-rwd { display:flex; gap:8px; font-family:'VT323'; font-size:11px; color:#ffd700; margin-top:3px; flex-wrap:wrap; }
.codex-ach-rwd span { background:#0a0520; border:1px solid #2a1a4e; padding:2px 6px; }

/* ============================================
   BASE DEFENCE
   ============================================ */
.bd-panel {
  width: min(940px, 96vw); max-height: 94vh; display: flex; flex-direction: column;
  background: linear-gradient(160deg, #0a1220, #060a12 60%);
  border: 1px solid #ff5f7a44;
  box-shadow: 0 0 0 1px #000, 0 22px 70px #000c, inset 0 1px 0 #ffffff10;
  padding: 14px; position: relative; overflow: hidden;
}
.bd-panel::before {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(120% 60% at 50% -10%, #ff5f7a1c, transparent 70%);
}
.bd-head { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; position: relative; flex-wrap: wrap; }
.bd-title {
  font-family: 'VT323', monospace; font-size: 22px; letter-spacing: 0.16em;
  color: #ffc3cd; text-shadow: 0 0 14px #ff5f7a66;
}
.bd-stat {
  font-family: 'VT323', monospace; font-size: 14px; letter-spacing: 0.1em;
  color: #9fb3c8; border: 1px solid #ffffff18; background: #ffffff08; padding: 3px 10px;
}
.bd-stat b { color: #e9f4ff; }
.bd-stat b.crit { color: #ff7a8c; animation: bdPulse 0.7s infinite; }
@keyframes bdPulse { 0%,100% { opacity: 1; } 50% { opacity: 0.4; } }
.bd-head .prosp-close { margin-left: auto; }

.bd-canvas {
  width: 100%; height: min(46vh, 340px); display: block;
  border: 1px solid #ffffff14; background: #05080e; cursor: crosshair;
  box-shadow: inset 0 0 60px #000a;
}

.bd-bar { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin-top: 10px; }
.bd-tower {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
  padding: 8px 9px; cursor: pointer; text-align: left;
  border: 1px solid #ffffff18; background: #ffffff08; color: var(--ink);
  transition: all 0.14s;
}
.bd-tower:hover { background: #ffffff12; }
.bd-tower.on {
  border-color: var(--tc); background: color-mix(in srgb, var(--tc) 14%, transparent);
  box-shadow: 0 0 16px color-mix(in srgb, var(--tc) 40%, transparent), inset 0 1px 0 #ffffff18;
}
.bd-tower-name { font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.08em; color: var(--tc); }
.bd-tower-cost { font-family: 'VT323', monospace; font-size: 13px; color: #ffd166; }
.bd-tower-desc { font-size: 10px; line-height: 1.25; opacity: 0.62; }

.bd-actions { display: flex; align-items: center; gap: 8px; margin-top: 10px; }
.bd-sel { font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.08em; color: #cfe6ff; }
.bd-preview {
  display: block;
  font-style: normal;
  font-size: 11px;
  letter-spacing: 0.06em;
  opacity: 0.7;
  margin-top: 2px;
}
.bd-spells {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 8px;
}
.bd-spell {
  font-family: 'VT323', monospace;
  font-size: 14px;
  letter-spacing: 0.1em;
  color: #cfe6ff;
  background: linear-gradient(180deg, #1a2834, #0b1218);
  border: 1px solid rgba(95, 214, 255, 0.28);
  padding: 8px 10px;
  cursor: pointer;
}
.bd-spell i {
  display: block;
  font-style: normal;
  font-size: 11px;
  opacity: 0.7;
  margin-top: 2px;
}
.bd-spell:disabled {
  color: #6a7a88;
  border-color: #ffffff14;
  cursor: default;
}

.bd-over {
  position: absolute; inset: 0; z-index: 4;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px;
  background: radial-gradient(60% 60% at 50% 45%, #200610e8, #03060ce8);
  backdrop-filter: blur(2px);
}
.bd-over-title {
  font-family: 'VT323', monospace; font-size: 30px; letter-spacing: 0.2em;
  color: #ff7a8c; text-shadow: 0 0 22px #ff5f7a88;
}
.bd-over-sub { font-size: 12px; color: #cfe0f0; opacity: 0.85; max-width: 70%; text-align: center; }
.bd-over-actions { display: flex; gap: 10px; margin-top: 6px; }

@media (max-width: 620px) {
  .bd-bar { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bd-canvas { height: 36vh; }
  .bd-spells { margin-top: 6px; }
  .pause-box { padding: 22px 18px; }
  .pause-sheet { min-width: 0; }
}

/* ============================================
   THE PATH — guided walk through every system
   ============================================ */
.path-wrap { margin-bottom: 18px; }
.path-head { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.path-title {
  font-family: 'VT323', monospace; font-size: 16px; letter-spacing: 0.18em;
  color: #ffd98a; text-shadow: 0 0 12px #ffb84d55;
}
.path-count { font-family: 'VT323', monospace; font-size: 14px; color: var(--ink-dim); }
.path-bar {
  flex: 1 1 auto; height: 5px; background: #0a0612;
  border: 1px solid #2a1a4e; overflow: hidden;
}
.path-bar i {
  display: block; height: 100%;
  background: linear-gradient(90deg, #c8912f, #ffd98a);
  box-shadow: 0 0 10px #ffb84d88; transition: width 0.5s ease;
}

.path-step {
  position: relative; padding: 12px 14px;
  background: linear-gradient(150deg, #120a1e, #08050f 65%);
  border: 1px solid #3a2a5e;
  box-shadow: inset 0 1px 0 #ffffff0e, 0 8px 24px #0008;
}
.path-step::before {
  content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px;
  background: #4a3a6e;
}
.path-step.ready { border-color: #ffd98a66; }
.path-step.ready::before { background: linear-gradient(180deg, #ffd98a, #c8912f); box-shadow: 0 0 14px #ffb84daa; }

.path-step-top { display: flex; gap: 11px; align-items: flex-start; }
.path-step-icon {
  font-size: 24px; line-height: 1; flex: 0 0 auto;
  filter: drop-shadow(0 0 8px #ffb84d55);
}
.path-step-text { min-width: 0; }
.path-step-title {
  font-family: 'VT323', monospace; font-size: 19px; letter-spacing: 0.08em;
  color: var(--ink);
}
.path-step-why { font-size: 11.5px; line-height: 1.45; color: var(--ink-dim); margin-top: 2px; }

.path-step-goal {
  display: flex; align-items: center; gap: 8px; margin-top: 10px;
  font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.06em;
  color: #cfe6ff; padding: 6px 9px; background: #ffffff07; border: 1px solid #ffffff12;
}
.path-tick { color: #4a3a6e; font-size: 15px; }
.path-tick.on { color: #4dff91; text-shadow: 0 0 10px #4dff9188; }

.path-step-foot { display: flex; align-items: center; gap: 10px; margin-top: 10px; }
.path-rwd { font-family: 'VT323', monospace; font-size: 14px; color: #ffd166; letter-spacing: 0.05em; }
.path-btn {
  margin-left: auto; font-family: 'VT323', monospace; font-size: 15px;
  letter-spacing: 0.12em; padding: 7px 16px; cursor: pointer;
  border: 1px solid #ffffff24; background: #ffffff0c; color: var(--ink);
  transition: all 0.14s;
}
.path-btn.go:hover { background: #ffffff18; border-color: #7cd6ff88; color: #cfe6ff; }
.path-btn.claim {
  border-color: #ffd98a; color: #ffe9c0; background: #c8912f26;
  animation: pathPulse 1.5s infinite;
}
.path-btn.claim:hover { background: #c8912f44; }
@keyframes pathPulse {
  0%, 100% { box-shadow: 0 0 0 #ffb84d00; }
  50%      { box-shadow: 0 0 18px #ffb84d77; }
}

.path-trail { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 9px; }
.path-trail-dot {
  font-size: 14px; opacity: 0.42; line-height: 1;
  padding: 3px 4px; background: #0a0612; border: 1px solid #1a0a2e;
}
.path-done-all {
  padding: 14px; font-family: 'VT323', monospace; font-size: 15px;
  color: #b6ffd2; background: #4dff910d; border: 1px solid #4dff9133;
  letter-spacing: 0.05em;
}

/* ============================================
   WEAPON SYNERGIES — smith list + in-run tags
   ============================================ */
.syn-intro {
  font-size: 11.5px; line-height: 1.5; color: var(--ink-dim);
  padding: 9px 11px; margin-bottom: 10px;
  background: #ffffff06; border-left: 2px solid #7cd6ff66;
}
.syn-wrap { display: flex; flex-direction: column; gap: 7px; }
.syn-row {
  display: flex; gap: 11px; align-items: flex-start; padding: 9px 11px;
  background: #0a0612; border: 1px solid #1f1436; opacity: 0.62;
  transition: all 0.16s;
}
.syn-row.done {
  opacity: 1; border-color: var(--sc);
  background: linear-gradient(100deg, color-mix(in srgb, var(--sc) 12%, #0a0612), #0a0612 60%);
  box-shadow: inset 0 0 22px color-mix(in srgb, var(--sc) 14%, transparent);
}
.syn-icon { font-size: 22px; line-height: 1; flex: 0 0 auto; }
.syn-row.done .syn-icon { filter: drop-shadow(0 0 8px var(--sc)); }
.syn-body { flex: 1 1 auto; min-width: 0; }
.syn-name {
  font-family: 'VT323', monospace; font-size: 17px; letter-spacing: 0.07em;
  color: var(--ink); display: flex; align-items: center; gap: 7px;
}
.syn-row.done .syn-name { color: var(--sc); text-shadow: 0 0 12px color-mix(in srgb, var(--sc) 55%, transparent); }
.syn-trinity {
  font-family: 'VT323', monospace; font-size: 10px; letter-spacing: 0.2em;
  font-style: normal; color: #ffd166; border: 1px solid #ffd16655;
  padding: 1px 5px; background: #ffd1660f;
}
.syn-desc { font-size: 11px; color: var(--ink-dim); margin-top: 1px; }
.syn-weapons { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 6px; }
.syn-w {
  font-size: 10px; padding: 2px 7px; letter-spacing: 0.04em;
  border: 1px dashed #ffffff1f; color: #8794a8; background: #ffffff05;
}
.syn-w.have { border-style: solid; border-color: var(--sc); color: var(--ink); background: color-mix(in srgb, var(--sc) 12%, transparent); }
.syn-count {
  font-family: 'VT323', monospace; font-size: 16px; color: var(--ink-dim);
  flex: 0 0 auto; align-self: center;
}
.syn-row.done .syn-count { color: var(--sc); }

.hud-sets {
  position: fixed; left: 10px; top: 96px; z-index: 30;
  display: flex; flex-direction: column; gap: 4px; pointer-events: none;
}
.hud-set {
  display: flex; align-items: center; gap: 5px;
  font-family: 'VT323', monospace; font-size: 12px; letter-spacing: 0.1em;
  color: var(--sc); padding: 2px 8px 2px 5px;
  background: #05080ecc; border: 1px solid color-mix(in srgb, var(--sc) 55%, transparent);
  border-left-width: 3px;
  text-shadow: 0 0 8px color-mix(in srgb, var(--sc) 60%, transparent);
  animation: setIn 0.45s ease both;
}
.hud-set i { font-style: normal; font-size: 13px; }
@keyframes setIn {
  from { opacity: 0; transform: translateX(-14px); }
  to   { opacity: 1; transform: none; }
}

/* ============================================
   GEAR SETS
   ============================================ */
.gear-sets { margin-top: 12px; }
.gset-row {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center;
  gap: 8px; padding: 8px 10px; margin-top: 6px;
  background: #0a0612; border: 1px solid #1f1436; border-left: 3px solid var(--sc);
}
.gset-icon { font-size: 17px; line-height: 1; }
.gset-name {
  font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.07em;
  color: var(--sc); text-shadow: 0 0 10px color-mix(in srgb, var(--sc) 45%, transparent);
}
.gset-count { font-family: 'VT323', monospace; font-size: 14px; color: var(--ink-dim); }
.gset-tiers { grid-column: 1 / -1; display: flex; flex-direction: column; gap: 2px; margin-top: 3px; }
.gset-tier { font-size: 10.5px; color: #55506a; display: flex; gap: 6px; }
.gset-tier b {
  font-family: 'VT323', monospace; font-size: 12px; color: #55506a;
  min-width: 13px; text-align: center; border: 1px solid #2a1a4e;
}
.gset-tier.on { color: var(--ink); }
.gset-tier.on b { color: var(--sc); border-color: var(--sc); }

.gear-set-tag {
  font-style: normal; font-size: 9.5px; letter-spacing: 0.06em;
  margin-left: 7px; padding: 1px 5px; color: var(--sc);
  border: 1px solid color-mix(in srgb, var(--sc) 45%, transparent);
  background: color-mix(in srgb, var(--sc) 10%, transparent);
  white-space: nowrap;
}

/* ============================================
   PET TCG
   ============================================ */
.tcg-empty {
  padding: 30px; text-align: center; font-family: 'VT323', monospace;
  font-size: 15px; color: var(--ink-dim); letter-spacing: 0.05em;
}
.tcg-card-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr));
  gap: 8px;
}
.tcg-card {
  display: flex; flex-direction: column; gap: 3px; text-align: left;
  padding: 8px; cursor: pointer;
  background: linear-gradient(160deg, #150c22, #0a0612 70%);
  border: 1px solid var(--rc, #3a2a5e); border-left-width: 3px;
  box-shadow: inset 0 1px 0 #ffffff0c;
  transition: transform 0.12s, box-shadow 0.12s;
  color: var(--ink);
}
.tcg-card:not(:disabled):hover { transform: translateY(-2px); box-shadow: 0 6px 14px #0008, 0 0 14px color-mix(in srgb, var(--rc, #7cd6ff) 35%, transparent); }
.tcg-card:disabled { opacity: 0.32; cursor: not-allowed; }
.tcg-card.small { padding: 6px; }
.tcg-card-top { display: flex; align-items: center; justify-content: space-between; }
.tcg-card-cost {
  font-family: 'VT323', monospace; font-size: 14px; color: #fff44d;
  border: 1px solid #fff44d55; border-radius: 50%; width: 20px; height: 20px;
  display: flex; align-items: center; justify-content: center;
  background: #fff44d12;
}
.tcg-card-name { font-family: 'VT323', monospace; font-size: 13px; letter-spacing: 0.03em; line-height: 1.15; }
.tcg-card-kind { font-size: 9.5px; letter-spacing: 0.1em; color: var(--rc, #8794a8); text-transform: uppercase; }
.tcg-card-power { font-family: 'VT323', monospace; font-size: 16px; color: #ff8a8a; margin-top: 1px; }
.tcg-card-type {
  align-self: flex-start; font-size: 8.5px; letter-spacing: 0.12em;
  color: var(--tc); border: 1px solid color-mix(in srgb, var(--tc) 55%, transparent);
  background: color-mix(in srgb, var(--tc) 12%, transparent);
  padding: 1px 5px; margin-top: 2px;
}

.tcg-pet-picker { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
.tcg-pet-chip {
  font-family: 'VT323', monospace; font-size: 13px; letter-spacing: 0.05em;
  padding: 6px 12px; cursor: pointer;
  background: #ffffff08; border: 1px solid #ffffff20; color: var(--ink);
}
.tcg-pet-chip i { font-style: normal; opacity: 0.65; margin-left: 4px; }
.tcg-pet-chip.on { border-color: #ff7a1a; background: #ff7a1a1c; color: #ffcf9a; }
.tcg-pet-chip.invalid { opacity: 0.55; }
.tcg-pet-nodeck { color: #ff6a7a; font-size: 10px; margin-left: 4px; }

.tcg-deck-count {
  font-family: 'VT323', monospace; font-size: 14px; color: var(--ink-dim);
  margin-bottom: 8px; letter-spacing: 0.05em;
}
.tcg-deck-warn { color: #ff8a8a; }
.tcg-deck-hint { font-size: 11px; color: var(--ink-dim); margin-top: 10px; line-height: 1.5; opacity: 0.8; }

.tcg-board { display: flex; flex-direction: column; gap: 8px; }
.tcg-side { display: flex; flex-direction: column; gap: 3px; }
.tcg-side-label { font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.08em; color: var(--ink); }
.tcg-hpbar { height: 10px; background: #1a0a2e; border: 1px solid #000; overflow: hidden; }
.tcg-hpbar i { display: block; height: 100%; background: linear-gradient(90deg, #4dff91, #b6ffd2); transition: width 0.4s ease; }
.tcg-hpbar.foe i { background: linear-gradient(90deg, #ff5566, #ffb3bb); }
.tcg-hptext { font-family: 'VT323', monospace; font-size: 12px; color: var(--ink-dim); }
.tcg-energy { display: flex; gap: 3px; }
.tcg-energy i { width: 12px; height: 12px; border: 1px solid #fff44d55; background: #0a0612; }
.tcg-energy i.on { background: #fff44d; box-shadow: 0 0 6px #fff44daa; }
.tcg-vs { text-align: center; font-family: 'VT323', monospace; font-size: 13px; color: var(--ink-dim); letter-spacing: 0.15em; }

.tcg-log {
  max-height: 92px; overflow-y: auto; padding: 6px 8px;
  background: #05080e; border: 1px solid #ffffff14; font-size: 11px;
}
.tcg-log-row { line-height: 1.5; }
.tcg-log-row.you { color: #b6ffd2; }
.tcg-log-row.foe { color: #ffb3bb; }

.tcg-hand { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }

.tcg-result { text-align: center; padding: 14px; }
.tcg-result-title {
  font-family: 'VT323', monospace; font-size: 26px; letter-spacing: 0.15em;
  text-shadow: 0 0 16px currentColor;
}
.tcg-result.you .tcg-result-title { color: #4dff91; }
.tcg-result.foe .tcg-result-title { color: #ff5566; }
.tcg-result.draw .tcg-result-title { color: #ffd166; }
.tcg-result-actions { display: flex; justify-content: center; gap: 10px; margin-top: 10px; }

/* ============================================
   TOAST HOST — every reward/claim/loot, one queue
   ============================================ */
.toast-host {
  position: fixed; top: 14px; right: 14px; z-index: 20000;
  display: flex; flex-direction: column; gap: 8px;
  pointer-events: none; max-width: min(320px, 86vw);
}
.toast-item {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 14px 9px 11px;
  background: linear-gradient(150deg, #150c22ee, #0a0612ee 75%);
  border: 1px solid var(--tc, #7cd6ff55); border-left-width: 4px;
  box-shadow: 0 8px 24px #000a, 0 0 18px color-mix(in srgb, var(--tc, #7cd6ff) 25%, transparent), inset 0 1px 0 #ffffff0e;
  animation: toastIn 0.32s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
}
.toast-item.leaving { animation: toastOut 0.3s ease-in both; }
@keyframes toastIn {
  from { opacity: 0; transform: translateX(60px) scale(0.94); }
  to   { opacity: 1; transform: none; }
}
@keyframes toastOut {
  from { opacity: 1; transform: none; }
  to   { opacity: 0; transform: translateX(60px) scale(0.94); }
}
.toast-icon { font-size: 22px; line-height: 1; flex: 0 0 auto; filter: drop-shadow(0 0 6px color-mix(in srgb, var(--tc, #7cd6ff) 60%, transparent)); }
.toast-title {
  font-family: 'VT323', monospace; font-size: 15px; letter-spacing: 0.05em;
  color: var(--tc, #cfe6ff);
}
.toast-text { font-size: 11px; color: var(--ink-dim); margin-top: 1px; }

.toast-item.t-gold      { --tc: #ffd166; }
.toast-item.t-gem       { --tc: #4dffd4; }
.toast-item.t-common    { --tc: #9a8fa6; }
.toast-item.t-magic     { --tc: #4dc4ff; }
.toast-item.t-rare      { --tc: #ffd166; }
.toast-item.t-epic      { --tc: #b362ff; }
.toast-item.t-legendary { --tc: #ff7a1a; }
.toast-item.t-mythical  { --tc: #ff3146; }
.toast-item.t-achievement { --tc: #ffd700; }
.toast-item.t-xp        { --tc: #6dff9e; }
.toast-item.t-default   { --tc: #7cd6ff; }

@media (max-width: 620px) {
  .toast-host { top: auto; bottom: 90px; right: 8px; left: 8px; max-width: none; align-items: flex-end; }
  .toast-item { width: min(320px, 100%); }
}

/* ============================================
   JOY STATS — compact HP/XP/score readout near the joysticks
   ============================================ */
.joy-stats {
  position: fixed; left: 50%; bottom: 108px; transform: translateX(-50%);
  display: flex; gap: 10px; align-items: center;
  pointer-events: none; z-index: 5;
}
.joy-stat { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.joy-stat-label {
  font-family: 'VT323', monospace; font-size: 10px; letter-spacing: 0.25em;
  opacity: 0.75;
}
.joy-stat.hp .joy-stat-label { color: #ff8a8a; }
.joy-stat.xp .joy-stat-label { color: #6dff9e; }
.joy-stat.score .joy-stat-label { color: #ffd166; }
.joy-stat-bar {
  width: 58px; height: 5px; background: #05080ea0;
  border: 1px solid #ffffff20; overflow: hidden;
}
.joy-stat-bar i { display: block; height: 100%; transition: width 0.2s ease; }
.joy-stat.hp .joy-stat-bar i { background: linear-gradient(90deg, #ff3146, #ff8a8a); box-shadow: 0 0 8px #ff314688; }
.joy-stat.xp .joy-stat-bar i { background: linear-gradient(90deg, #4dffd4, #b6ffec); box-shadow: 0 0 8px #4dffd488; }
.joy-stat-val {
  font-family: 'VT323', monospace; font-size: 12px; color: #fff;
  text-shadow: 0 0 6px #000;
}
.joy-stat-val.big { font-size: 15px; color: #ffd166; text-shadow: 0 0 10px #ffd16688; }

@media (max-width: 480px) {
  .joy-stats { bottom: 96px; gap: 7px; }
  .joy-stat-bar { width: 44px; }
}

/* ============================================
   COMPANION RESCUE HUD
   ============================================ */
.hud-companion {
  position: fixed; top: 42px; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  padding: 4px 14px; z-index: 1400; pointer-events: none;
  font-family: 'VT323', monospace;
  background: linear-gradient(180deg, rgba(122,217,107,0.14), rgba(0,0,0,0.5));
  border: 1px solid rgba(122,217,107,0.4);
}
.hud-companion-label { font-size: 10px; letter-spacing: 0.22em; color: #c8ffc0; }
.hud-companion-bar {
  width: 140px; height: 5px; background: #05080ea0; border: 1px solid #ffffff20;
  overflow: hidden;
}
.hud-companion-bar i {
  display: block; height: 100%; background: linear-gradient(90deg, #4dff91, #b6ffd2);
  box-shadow: 0 0 8px #4dff9188; transition: width 0.25s ease;
}
.hud-companion.down { border-color: #ff5566; background: linear-gradient(180deg, rgba(255,85,102,0.18), rgba(0,0,0,0.5)); }
.hud-companion.down .hud-companion-label { color: #ffb3bb; }
.hud-companion.down .hud-companion-bar i { background: #55424a; box-shadow: none; }

/* ============================================
   COMPANIONS — visible at the base once rescued
   ============================================ */
.base-companions { display: flex; gap: 8px; margin-bottom: 14px; flex-wrap: wrap; }
.base-comp {
  display: flex; align-items: center; gap: 6px;
  padding: 5px 10px; background: #ffffff06; border: 1px solid #ffffff14;
  opacity: 0.5;
}
.base-comp.here { opacity: 1; border-color: var(--cc); background: color-mix(in srgb, var(--cc) 10%, transparent); }
.base-comp-dot {
  width: 8px; height: 8px; border-radius: 50%; background: #3a3a3a; flex: 0 0 auto;
}
.base-comp.here .base-comp-dot { background: var(--cc); box-shadow: 0 0 8px var(--cc); }
.base-comp-name { font-family: 'VT323', monospace; font-size: 14px; color: var(--ink); }
.base-comp.here .base-comp-name { color: var(--cc); }
.base-comp-role { font-size: 9.5px; color: var(--ink-dim); letter-spacing: 0.04em; }

.npc-host-line {
  font-family: 'VT323', monospace; font-size: 13px; font-style: italic;
  color: var(--nc, #cfe6ff); letter-spacing: 0.02em; line-height: 1.4;
  padding: 6px 10px; margin-bottom: 10px;
  background: color-mix(in srgb, var(--nc, #7cd6ff) 8%, transparent);
  border-left: 2px solid var(--nc, #7cd6ff);
}
.npc-host-line i { font-style: normal; opacity: 0.7; }

/* ============================================
   EXPLORATION
   ============================================ */
.expl-launch {
  display: block; width: 100%; text-align: left; margin-bottom: 14px;
  padding: 10px 14px; cursor: pointer;
  font-family: 'VT323', monospace; font-size: 14px; letter-spacing: 0.03em;
  color: #cfe6ff; background: linear-gradient(120deg, #10202c, #0a0612);
  border: 1px solid #7cd6ff44; border-left: 3px solid #7cd6ff;
}
.expl-launch:hover { background: linear-gradient(120deg, #16303f, #0a0612); border-color: #7cd6ff88; }

.expl-panel { max-width: 640px; }

.expl-path { position: relative; height: 64px; margin: 10px 0 18px; }
.expl-track {
  position: absolute; left: 12px; right: 12px; top: 28px; height: 3px;
  background: #ffffff14; overflow: hidden;
}
.expl-track i { display: block; height: 100%; background: linear-gradient(90deg, #4dffd4, #7cd6ff); transition: width 0.1s linear; }
.expl-node {
  position: absolute; top: 12px;
  width: 30px; height: 30px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: #0a0612; border: 2px solid #3a2a5e;
  transform: translateX(-50%);
}
.expl-node:nth-child(1) { left: 0%; } .expl-node:nth-child(2) { left: 20%; }
.expl-node:nth-child(3) { left: 40%; } .expl-node:nth-child(4) { left: 60%; }
.expl-node:nth-child(5) { left: 80%; } .expl-node:nth-child(6) { left: 100%; }
.expl-node.t-trainer { border-color: #ffd166; }
.expl-node.t-encounter { border-color: #ff7a1a; }
.expl-node.t-loot { border-color: #4dc4ff; }
.expl-node.done { opacity: 0.4; }
.expl-node.current { box-shadow: 0 0 14px currentColor; animation: explPulse 1s ease-in-out infinite; }
@keyframes explPulse { 0%, 100% { transform: translateX(-50%) scale(1); } 50% { transform: translateX(-50%) scale(1.12); } }
.expl-walker {
  position: absolute; top: -6px; transform: translateX(-50%);
  font-size: 22px; transition: left 0.08s linear; z-index: 2;
  filter: drop-shadow(0 0 6px #7cd6ff88);
}
.expl-walker-pet { position: absolute; right: -8px; bottom: -4px; font-size: 12px; font-style: normal; }

.expl-status {
  text-align: center; font-family: 'VT323', monospace; font-size: 15px;
  color: var(--ink-dim); letter-spacing: 0.15em; padding: 20px 0;
}

.expl-popup {
  text-align: center; padding: 20px; animation: toastIn 0.3s ease both;
}
.expl-popup-icon { display: block; margin-bottom: 6px; }
.expl-popup-title { font-family: 'VT323', monospace; font-size: 17px; color: #cfe6ff; }
.expl-popup-text { font-size: 13px; color: #ffd166; margin-top: 4px; }

.expl-trainer {
  padding: 14px; background: linear-gradient(150deg, color-mix(in srgb, var(--tc) 10%, #0a0612), #0a0612 70%);
  border: 1px solid var(--tc);
}
.expl-trainer-name { font-family: 'VT323', monospace; font-size: 19px; color: var(--tc); letter-spacing: 0.05em; }
.expl-trainer-name i { font-style: normal; opacity: 0.7; font-size: 13px; margin-left: 6px; }
.expl-trainer-line { font-size: 12px; font-style: italic; color: var(--ink-dim); margin: 4px 0 12px; }
.expl-sub { font-family: 'VT323', monospace; font-size: 13px; color: var(--ink); margin-bottom: 8px; letter-spacing: 0.04em; }
.expl-stakes, .expl-prizes, .expl-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 10px; }
.expl-stake, .expl-prize {
  font-family: 'VT323', monospace; font-size: 13px; padding: 8px 12px; cursor: pointer;
  background: #ffffff08; border: 1px solid #ffffff24; color: var(--ink);
}
.expl-stake:hover, .expl-prize:hover { background: #ffffff14; }
.expl-stake.risky { border-color: #ff5566; color: #ffb3bb; }

.expl-done { text-align: center; padding: 24px 10px; }
.expl-done-title {
  font-family: 'VT323', monospace; font-size: 24px; letter-spacing: 0.15em;
  color: #4dffd4; text-shadow: 0 0 14px #4dffd488; margin-bottom: 10px;
}
.expl-done-haul { font-family: 'VT323', monospace; font-size: 15px; color: #ffd166; margin-bottom: 16px; }

/* ============================================
   STAR RAID — menu, hangar and upgrades
   ============================================ */
.raid-menu {
  width: min(520px, 92vw); max-height: 92vh; overflow-y: auto;
  padding: 22px 22px 18px;
  background: radial-gradient(120% 70% at 50% -10%, #12283c 0%, #050a12 65%);
  border: 1px solid #4dc4ff33;
  box-shadow: 0 20px 60px #000c, inset 0 0 60px rgba(77,196,255,0.04);
}
.raid-menu-head { margin-bottom: 12px; }
.raid-menu-title {
  font-family: 'VT323', monospace; font-size: 26px; letter-spacing: 0.1em;
  color: #cfe9ff; text-shadow: 0 0 18px #4dc4ff66;
}
.raid-menu-sub { font-size: 12px; color: var(--ink-dim); margin-top: 3px; }
.raid-menu-ship {
  margin-top: 6px; font-family: 'VT323', monospace; font-size: 13px;
  color: var(--sc, #5fd6ff); letter-spacing: 0.04em;
}
.raid-menu-ship b { text-shadow: 0 0 8px color-mix(in srgb, var(--sc, #5fd6ff) 60%, transparent); }

.raid-currency-row { display: flex; gap: 8px; margin-bottom: 14px; }
.raid-currency-chip {
  display: flex; align-items: center; gap: 5px;
  font-family: 'VT323', monospace; font-size: 13px; color: #ffd166;
  background: linear-gradient(180deg, rgba(255,255,255,0.09), rgba(0,0,0,0.35));
  border: 1px solid #ffffff20; padding: 3px 10px;
}

.raid-section-label {
  font-family: 'VT323', monospace; font-size: 12px; letter-spacing: 0.24em;
  color: var(--accent-2); margin: 4px 0 7px;
}

.raid-stage-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; margin-bottom: 14px; }
.raid-stage-card {
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  padding: 10px 4px; cursor: pointer;
  background: linear-gradient(170deg, rgba(16,32,50,0.9), rgba(5,10,18,0.9));
  border: 1px solid #ffffff1c;
  transition: border-color 0.14s, box-shadow 0.14s;
}
.raid-stage-card:hover:not(.locked) { border-color: #7cd6ff88; }
.raid-stage-card.sel { border-color: #ffd166; box-shadow: 0 0 16px rgba(255,209,102,0.3), inset 0 0 14px rgba(255,209,102,0.06); }
.raid-stage-card.locked { opacity: 0.4; cursor: not-allowed; }
.raid-stage-lock { font-size: 20px; }
.raid-stage-name { font-family: 'VT323', monospace; font-size: 12.5px; color: #eaf7ff; text-align: center; letter-spacing: 0.03em; }
.raid-stage-boss { font-size: 8.5px; color: #ff8a95; letter-spacing: 0.06em; text-align: center; }

.raid-mode-desc { font-size: 11.5px; color: var(--ink-dim); line-height: 1.4; margin-bottom: 14px; }

.raid-menu-actions { display: flex; gap: 8px; }
.raid-menu-actions .prosp-btn.go { flex: 1 1 auto; text-align: center; }

.raid-shop .raid-hangar { max-height: 30vh; overflow-y: auto; margin-bottom: 14px; }
.raid-upgrade-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(min(140px, 100%), 1fr));
  gap: 8px; max-height: 32vh; overflow-y: auto; margin-bottom: 8px;
}
.raid-upgrade-card {
  padding: 9px 10px; background: #ffffff08; border: 1px solid #ffffff18;
  display: flex; flex-direction: column; gap: 6px;
}
.raid-upgrade-card.maxed { border-color: #4dff9155; background: #4dff9108; }
.raid-upgrade-top { display: flex; align-items: center; gap: 5px; }
.raid-upgrade-icon { font-size: 16px; }
.raid-upgrade-name { font-family: 'VT323', monospace; font-size: 13px; color: var(--ink); flex: 1; }
.raid-upgrade-lvl { font-family: 'VT323', monospace; font-size: 12px; color: #4dffd4; }
.raid-upgrade-lvl i { font-style: normal; opacity: 0.6; }
.raid-upgrade-pips { display: flex; gap: 2px; }
.raid-upgrade-pips i { flex: 1; height: 3px; background: #ffffff18; }
.raid-upgrade-pips i.on { background: #4dffd4; box-shadow: 0 0 5px #4dffd488; }
.raid-upgrade-max { font-family: 'VT323', monospace; font-size: 12px; color: #4dff91; text-align: center; }

/* ============================================================================
   MAIN MENU — DEAD CELLS SCI-FI ROGUE-LITE MASTER STYLING
   ========================================================================= */
.menu-shell {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at center, #0c0818 0%, #05020a 70%, #010004 100%);
  overflow: hidden;
  z-index: 10;
}

.menu-motes {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.menu-mote {
  position: absolute;
  bottom: -20px;
  left: var(--left, 50%);
  width: var(--size, 4px);
  height: var(--size, 4px);
  border-radius: 50%;
  background: #4dffd4;
  box-shadow: 0 0 10px #4dffd4, 0 0 20px #4dc4ff;
  opacity: var(--alpha, 0.5);
  animation: moteRise var(--dur, 6s) ease-in infinite var(--delay, 0s);
}

@keyframes moteRise {
  0% { transform: translateY(0) scale(0.6); opacity: 0; }
  20% { opacity: var(--alpha, 0.5); }
  80% { opacity: var(--alpha, 0.5); }
  100% { transform: translateY(-110vh) scale(1.4); opacity: 0; }
}

.menu-card {
  position: relative;
  width: min(480px, 92vw);
  max-height: 94vh;
  background: linear-gradient(180deg, #110a22 0%, #090514 55%, #05020a 100%);
  border: 2px solid #3d2466;
  border-radius: 14px;
  padding: 32px 28px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.9),
    0 0 40px rgba(110, 50, 200, 0.35),
    inset 0 1px 0 rgba(180, 140, 255, 0.25),
    inset 0 0 30px rgba(0, 0, 0, 0.7);
  z-index: 2;
}

.menu-crest {
  position: relative;
  width: 90px;
  height: 90px;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.menu-crest-glow {
  position: absolute;
  inset: -10px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(77, 255, 212, 0.35) 0%, rgba(179, 98, 255, 0.15) 50%, transparent 70%);
  filter: blur(8px);
  animation: crestPulse 3s ease-in-out infinite alternate;
}

@keyframes crestPulse {
  from { transform: scale(0.9); opacity: 0.7; }
  to { transform: scale(1.15); opacity: 1; }
}

.menu-crest-ring {
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 2px dashed rgba(77, 255, 212, 0.4);
  animation: ringRotate 24s linear infinite;
}

@keyframes ringRotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.menu-crest-icon {
  position: relative;
  z-index: 2;
  filter: drop-shadow(0 0 14px rgba(77, 255, 212, 0.8));
}

.menu-brand {
  margin-bottom: 20px;
}

.menu-title {
  font-family: 'VT323', monospace;
  font-size: clamp(42px, 9vw, 56px);
  margin: 0;
  line-height: 0.95;
  letter-spacing: 0.14em;
  background: linear-gradient(180deg, #ffffff 0%, #ffd166 40%, #ff8a1a 85%, #b51d28 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 16px rgba(255, 138, 26, 0.6));
}

.menu-subtitle {
  font-family: 'VT323', monospace;
  font-size: 19px;
  color: #4dffd4;
  letter-spacing: 0.45em;
  margin-top: 4px;
  text-shadow: 0 0 10px rgba(77, 255, 212, 0.6);
}

.menu-tagline {
  font-family: 'VT323', monospace;
  font-size: 13px;
  color: #8a7c9f;
  letter-spacing: 0.18em;
  margin-top: 6px;
}

.menu-profile-pill {
  width: 100%;
  background: rgba(22, 12, 42, 0.85);
  border: 1px solid #3d2466;
  border-radius: 8px;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.5);
}

.menu-profile-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #180d30;
  border: 2px solid #4dffd4;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  box-shadow: 0 0 10px rgba(77, 255, 212, 0.4);
}

.menu-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.menu-profile-info {
  flex: 1;
  text-align: left;
}

.menu-profile-name {
  font-family: 'VT323', monospace;
  font-size: 18px;
  color: #ffffff;
  letter-spacing: 0.05em;
}

.menu-profile-rank {
  font-family: 'VT323', monospace;
  font-size: 13px;
  color: #a094b8;
}

.menu-profile-stats {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  font-family: 'VT323', monospace;
  font-size: 15px;
}

.menu-cur-gold {
  color: #ffd166;
  text-shadow: 0 0 6px rgba(255, 209, 102, 0.4);
}

.menu-cur-sp {
  color: #b362ff;
  text-shadow: 0 0 6px rgba(179, 98, 255, 0.4);
}

.menu-actions {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.menu-btn-play {
  position: relative;
  width: 100%;
  padding: 14px 20px;
  font-family: 'VT323', monospace;
  font-size: 24px;
  letter-spacing: 0.12em;
  color: #06030c;
  background: linear-gradient(90deg, #ffd166, #ff9f1c, #ffd166);
  background-size: 200% auto;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-weight: bold;
  overflow: hidden;
  box-shadow: 0 0 20px rgba(255, 159, 28, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.6);
  transition: all 0.2s ease;
}

.menu-btn-play:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 0 30px rgba(255, 159, 28, 0.8), inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.menu-btn-play:active {
  transform: translateY(1px) scale(0.99);
}

.menu-btn-camp {
  width: 100%;
  padding: 11px 18px;
  font-family: 'VT323', monospace;
  font-size: 19px;
  letter-spacing: 0.1em;
  color: #ffd166;
  background: #190f30;
  border: 1.5px solid #ffd16688;
  border-radius: 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-shadow: 0 0 12px rgba(255, 209, 102, 0.2);
  transition: all 0.18s ease;
}

.menu-btn-camp:hover {
  background: #241444;
  border-color: #ffd166;
  transform: translateY(-1px);
  box-shadow: 0 0 18px rgba(255, 209, 102, 0.4);
}

.menu-btn-reset {
  background: none;
  border: none;
  font-family: 'VT323', monospace;
  font-size: 13px;
  color: #70588a;
  cursor: pointer;
  padding: 4px;
  transition: color 0.15s;
}

.menu-btn-reset:hover {
  color: #ff3355;
}

.menu-footer-stats {
  font-family: 'VT323', monospace;
  font-size: 14px;
  color: #8a7c9f;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.menu-footer-stats b {
  color: #4dffd4;
}

.menu-dot {
  color: #443060;
}

.menu-controls-bar {
  font-family: 'VT323', monospace;
  font-size: 12px;
  color: #5c4e70;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
}

